-- Parte 2: recebível único de intermediação na entrega das chaves, sem contrato de administração.
-- Depende da migration 20261215120000 (parte 1). Rollback: supabase/rollback/20261215130000_locacao_intermediacao_financeiro.sql
BEGIN;
SELECT set_config('lock_timeout', '5s', true);

-- Modelos próprios separados dos vigentes com administração.
ALTER TABLE public.locacao_modelos DROP CONSTRAINT locacao_modelos_chave_check;
ALTER TABLE public.locacao_modelos ADD CONSTRAINT locacao_modelos_chave_check CHECK (chave IN ('fiador','caucao_dinheiro','caucao_imovel','seguro_porto','seguro_pottencial','seguro_tokio','seguro_almada','loft','fiador_intermediacao','caucao_dinheiro_intermediacao','caucao_imovel_intermediacao','seguro_porto_intermediacao','seguro_pottencial_intermediacao','seguro_tokio_intermediacao','seguro_almada_intermediacao','loft_intermediacao'));
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, $inter$fiador_intermediacao$inter$, 1, $inter$Fiador — só intermediação$inter$, $inter$residencial$inter$, $inter$fiador$inter$, NULL, $inter$FIADOR$inter$, $inter$[{"id": "p001", "t": "QUADRO RESUMO: Locador(es); Locatário(a); Imóvel; Destinação da Locação; Prazo da Locação; Valor e Vencimento do Aluguel; Primeiro Aluguel; Reajuste e Indexador; Encargos Locatícios; Contas de Consumo; Transferência de Titularidade; Garantia Locatícia; Inadimplência; Vistoria Inicial; Contestação da Vistoria; Conservação e Manutenção do Imóvel; Benfeitorias e Modificações; Vistoria Final e Revistoria; Rescisão e Multa Contratual; Desocupação e Aviso Prévio; Seguro Incêndio; Sublocação/Cessão; Preferência na Compra do Imóvel; LGPD; Disposições Gerais; Foro."}, {"id": "p002", "t": "PRÊAMBULO"}, {"id": "p003", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p004", "t": "[[LOCADOR]]"}, {"id": "p005", "t": "[[LOCATARIO]]"}, {"id": "p007", "t": "[[FIADOR]]"}, {"id": "p009", "t": "PARÁGRAFO 2º: O FIADOR declara ter pleno conhecimento das obrigações assumidas neste instrumento, responsabilizando-se solidariamente pelo cumprimento das obrigações locatícias, inclusive reajustes previstos contratualmente e encargos decorrentes da locação, até a efetiva devolução das chaves, observadas as disposições do artigo 39 da Lei nº 8.245/91."}, {"id": "p011", "t": "PARÁGRAFO 4º: Na hipótese de exoneração da fiança, o FIADOR deverá observar os procedimentos e prazos previstos na legislação vigente, permanecendo responsável pelas obrigações locatícias durante o período legal aplicável. O LOCATÁRIO deverá providenciar a substituição da garantia, quando exigível, no prazo e nas condições estabelecidos pela Lei nº 8.245/91."}, {"id": "p012", "t": "PARÁGRAFO 5º: O FIADOR responderá pelas obrigações decorrentes da locação, incluindo aluguéis, reajustes previstos neste contrato, encargos locatícios, multas e despesas legalmente exigíveis decorrentes do inadimplemento, observados os limites da garantia prestada e a legislação vigente."}, {"id": "p013", "t": "PARÁGRAFO 6º: Em caso de prorrogação da locação por prazo indeterminado, a responsabilidade do FIADOR permanecerá vigente, nos termos do artigo 39 da Lei nº 8.245/91, ressalvadas as hipóteses legais de exoneração da fiança."}, {"id": "p014", "t": "PARÁGRAFO 7º: Em caso de falecimento do FIADOR, a responsabilidade de seus herdeiros ficará limitada às obrigações vencidas até a data do falecimento, observados os limites da herança e o disposto no artigo 836 do Código Civil, devendo o LOCATÁRIO providenciar a substituição da garantia, nos termos da Lei nº 8.245/91."}, {"id": "p015", "t": "PARÁGRAFO 8º: Nas hipóteses legais de perda, exoneração ou insuficiência da garantia fidejussória, o LOCATÁRIO será notificado para apresentar nova garantia locatícia, no prazo de 30 (trinta) dias, observadas as disposições do artigo 40 da Lei nº 8.245/91, sob pena de adoção das medidas legais cabíveis."}, {"id": "p016", "t": "[[OBJETO]]"}, {"id": "p017", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p018", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p019", "t": "O imóvel identificado neste instrumento destina-se exclusivamente à MORADIA do LOCATÁRIO e dos moradores expressamente identificados neste contrato, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "residencial"}, {"id": "p020", "t": "O imóvel identificado neste instrumento destina-se exclusivamente ao uso COMERCIAL do LOCATÁRIO, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "comercial", "adaptado": true}, {"id": "p021", "t": "[[PRAZO]]"}, {"id": "p022", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), devendo ser pago pelo LOCATÁRIO até o dia [DIA_VENCIMENTO] de cada mês, conforme as condições estabelecidas neste instrumento."}, {"id": "p023", "t": "Cláusula 2º - O primeiro aluguel vencerá 30 (trinta) dias após a efetiva entrega das chaves ao LOCATÁRIO. Os aluguéis subsequentes vencerão todo dia [DIA_VENCIMENTO] de cada mês, observando-se, quando necessário, o cálculo proporcional dos períodos de ocupação, a fim de evitar cobrança em duplicidade."}, {"id": "p024", "t": "[[ADICIONAIS]]"}, {"id": "p025", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p026", "t": "Além do aluguel mensal, serão de responsabilidade do LOCATÁRIO os encargos locatícios expressamente atribuídos a ele neste contrato, os quais serão devidos a partir da efetiva entrega das chaves, observadas as disposições legais e contratuais aplicáveis."}, {"id": "p027", "t": "Cláusula 3º - O atraso no pagamento do aluguel ou de quaisquer encargos locatícios acarretará a incidência de multa moratória de 10% (dez por cento) sobre o valor devido, acrescida de juros de mora de 1% (um por cento) ao mês, calculados proporcionalmente aos dias de atraso, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p030", "t": "Cláusula 6º - O inadimplemento do aluguel ou de quaisquer encargos locatícios na data do vencimento constituirá o LOCATÁRIO em mora, independentemente de notificação, facultando ao LOCADOR adotar as medidas judiciais e extrajudiciais cabíveis, inclusive ação de despejo e cobrança, nos termos da Lei nº 8.245/91, sem prejuízo dos encargos moratórios previstos neste contrato."}, {"id": "p032", "t": "Cláusula 8º – O LOCATÁRIO declara estar ciente de que o inadimplemento das obrigações financeiras decorrentes deste contrato poderá ensejar o protesto dos respectivos débitos, observadas as exigências legais aplicáveis."}, {"id": "p033", "t": "Cláusula 9º - O inadimplemento das obrigações locatícias poderá ensejar a adoção das medidas judiciais cabíveis, bem como a comunicação dos débitos aos órgãos de proteção ao crédito, desde que observados os requisitos legais, inclusive quanto à legitimidade, exatidão e atualização das informações fornecidas."}, {"id": "p034", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p035", "t": "O valor do aluguel será reajustado anualmente, respeitado o intervalo mínimo permitido pela legislação vigente, mediante aplicação do índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), ou de outro índice oficial que venha a substituí-lo em caso de sua extinção, observadas as disposições legais aplicáveis."}, {"id": "p038", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p039", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p040", "t": "Cláusula 12º – O locatário obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das de ÁGUA, ELERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p041", "t": "DO DESCUMPRIMENTO E DAS PROVIDÊNCIAS ADMINISTRATIVAS:"}, {"id": "p045", "t": "Cláusula 14º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso para HABITAÇÃO.", "dest": "residencial"}, {"id": "p046", "t": "Cláusula 14º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso COMERCIAL.", "dest": "comercial", "adaptado": true}, {"id": "p048", "t": "Cláusula 16º - Fica permitido ao LOCATÁRIO realizar pequenos furos nas paredes do imóvel para a fixação de quadros, espelhos, suportes e objetos similares, desde que não comprometam a estrutura, as instalações hidráulicas ou elétricas. Fica expressamente vedada a realização de furos em azulejos, revestimentos cerâmicos e áreas impermeabilizadas, salvo mediante autorização prévia e por escrito do LOCADOR. Ao término da locação, o LOCATÁRIO deverá providenciar a adequada reparação dos furos realizados nas paredes, recompondo a pintura e o acabamento quando necessário, restituindo o imóvel nas condições em que o recebeu, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p049", "t": "Cláusula 17º - O LOCATÁRIO deverá devolver o imóvel com a pintura nas mesmas condições em que o recebeu, conforme descrito no laudo de vistoria inicial, responsabilizando-se pela reparação de manchas, riscos, alterações de cores, descascamentos ou danos decorrentes de uso inadequado ou de sua responsabilidade, ressalvado o desgaste natural decorrente do uso regular do imóvel."}, {"id": "p050", "t": "Cláusula 18º - O LOCATÁRIO deverá zelar pela conservação dos pisos, azulejos, armários, acessórios e demais itens que integram o imóvel, responsabilizando-se pelos danos que causar por ação, omissão ou uso inadequado, devendo providenciar o reparo ou a substituição dos itens danificados por outros de padrão, qualidade e características equivalentes aos originalmente existentes, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p052", "t": "Cláusula 20º - O LOCATÁRIO deverá verificar a tensão elétrica disponível nos pontos de energia do imóvel antes de conectar seus equipamentos e aparelhos eletrônicos, responsabilizando-se pelos danos decorrentes da utilização inadequada ou incompatível com a tensão disponível, desde que as instalações tenham sido entregues em condições regulares de funcionamento e que as informações disponíveis tenham sido corretamente fornecidas."}, {"id": "p053", "t": "Cláusula 21º - O LOCATÁRIO não poderá realizar modificações, alterações ou benfeitorias no imóvel sem prévia autorização, por escrito, do LOCADOR. Salvo ajuste expresso em contrário, as benfeitorias realizadas, ainda que autorizadas, incorporar-se-ão ao imóvel, sem direito de indenização ou retenção pelo LOCATÁRIO, nos termos do artigo 35 da Lei nº 8.245/91 e da Súmula 335 do STJ, ressalvadas as obrigações legais do LOCADOR relativas à conservação, segurança e habitabilidade do imóvel."}, {"id": "p054", "t": "Cláusula 22º - Compete ao LOCATÁRIO realizar os reparos e serviços de manutenção decorrentes do uso regular do imóvel, bem como reparar os danos causados por si, seus moradores, visitantes ou terceiros sob sua responsabilidade. Compete ao LOCADOR realizar os reparos relativos a vícios anteriores à locação, problemas estruturais e defeitos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, desde que não decorrentes de ação ou omissão do LOCATÁRIO."}, {"id": "p056", "t": "Cláusula 23º - O LOCADOR poderá exigir que o LOCATÁRIO remova modificações ou benfeitorias realizadas sem autorização prévia e por escrito, quando necessário à recomposição do imóvel às condições originais, correndo as despesas correspondentes por conta do LOCATÁRIO, desde que decorrentes de sua responsabilidade."}, {"id": "p057", "t": "Cláusula 24º - Ao término da locação, será realizada vistoria final para verificar as condições de conservação do imóvel, mediante comparação com o laudo de vistoria inicial, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p058", "t": "Parágrafo 1º: Caso sejam constatados danos ou irregularidades de responsabilidade do LOCATÁRIO, este será comunicado para que possa providenciar os respectivos reparos no prazo de 05 (cinco) dias corridos, ou outro prazo acordado entre as partes, sem prejuízo da cobrança de eventuais valores necessários à recomposição do imóvel."}, {"id": "p059", "t": "Parágrafo 2º: Caso o LOCATÁRIO não realize os reparos de sua responsabilidade, o LOCADOR poderá providenciá-los e exigir o ressarcimento dos respectivos custos, mediante apresentação dos comprovantes pertinentes, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p060", "t": "Parágrafo 3º: A vistoria final será realizada sem custo para o LOCATÁRIO. Caso seja necessária nova vistoria para verificação dos reparos executados, poderá ser cobrada taxa de revistoria no valor de R$ 150,00 (cento e cinquenta reais), desde que previamente informada e relacionada à necessidade de nova verificação de pendências de responsabilidade do LOCATÁRIO."}, {"id": "p061", "t": "Parágrafo 4º: A existência de danos ou pendências apontadas na vistoria não impedirá o recebimento das chaves nem a formalização da devolução do imóvel, permanecendo assegurado ao LOCADOR o direito de exigir o ressarcimento dos prejuízos comprovadamente atribuíveis ao LOCATÁRIO."}, {"id": "p062", "t": "Cláusula 25º - O LOCATÁRIO permitirá que o LOCADOR ou seu representante devidamente autorizado examine ou vistori? o imóvel, mediante prévio agendamento e comunicação com antecedência mínima de 48 (quarenta e oito) horas, em dia e horário previamente acordados entre as partes, respeitado o direito à privacidade e ao uso pacífico do imóvel."}, {"id": "p063", "t": "Cláusula 26º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade residencial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "residencial"}, {"id": "p064", "t": "Cláusula 26º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade comercial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "comercial", "adaptado": true}, {"id": "p065", "t": "Cláusula 27º - Em caso de desapropriação do imóvel, a locação será extinta, ficando o LOCADOR desobrigado das obrigações futuras decorrentes deste contrato, ressalvados os direitos do LOCATÁRIO de pleitear eventual indenização diretamente perante o poder público desapropriante, quando legalmente cabível."}, {"id": "p066", "t": "Cláusula 28º - O LOCATÁRIO obriga-se a respeitar as normas de convivência, os direitos de vizinhança, as regras condominiais e a legislação vigente, abstendo-se de praticar atos que comprometam a segurança, a tranquilidade, a higiene ou o sossego dos demais moradores."}, {"id": "p067", "t": "Parágrafo primeiro: O descumprimento das obrigações legais ou contratuais poderá ensejar a aplicação das medidas cabíveis, inclusive rescisão da locação, conforme a natureza e a gravidade da infração, observadas as disposições da Lei nº 8.245/91."}, {"id": "p068", "t": "Parágrafo segundo: Fica estipulada multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente à época da infração, aplicável em caso de descumprimento contratual que justifique sua incidência, observados os critérios de proporcionalidade, a natureza da obrigação descumprida e a legislação vigente."}, {"id": "p069", "t": "Parágrafo terceiro: Na hipótese de devolução antecipada do imóvel por iniciativa do LOCATÁRIO durante o prazo determinado deste contrato, será devida multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente, calculada proporcionalmente ao período restante do contrato, conforme o artigo 4º da Lei nº 8.245/91."}, {"id": "p070", "t": "Cláusula 29º - Fica o LOCATÁRIO isento do pagamento de multa contratual por desocupação voluntária do imóvel após o 12º (décimo segundo) mês de locação, tendo, porém, a obrigação de avisar por escrito com, no mínimo, 30 (trinta) dias de antecedência, ficando responsável pelo pagamento do aluguel e dos acessórios locatícios durante o período de aviso.", "cond": "isencao_multa"}, {"id": "p071", "t": "Parágrafo primeiro: A isenção da multa rescisória apenas caberá em benefício do LOCATÁRIO, caso esteja quite com todas as demais obrigações previstas neste instrumento. Caso contrário fica estipulada a multa contratual compensatória proporcionalmente ao período de cumprimento do contrato, em conformidade com a nova redação do artigo 4º, atribuída pela Lei no 12.112/2009, na qual incorrerá o LOCATÁRIO na hipótese de devolução do imóvel antes do prazo pactuado.", "cond": "isencao_multa"}, {"id": "p073", "t": "Cláusula 31º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p075", "t": "Parágrafo único: Na ausência do aviso prévio previsto nesta cláusula, o LOCADOR poderá exigir quantia correspondente a 01 (um) mês de aluguel e encargos vigentes na data da rescisão, conforme disposto no artigo 6º, parágrafo único, da Lei nº 8.245/91."}, {"id": "p076", "t": "Cláusula 33º - Fica eleito o foro da comarca onde se localiza o imóvel objeto desta locação para dirimir quaisquer controvérsias decorrentes deste contrato, ressalvadas as hipóteses legais de competência absoluta."}, {"id": "p077", "t": "Parágrafo único: Em caso de demanda judicial decorrente do descumprimento das obrigações contratuais, as partes responderão pelas custas e despesas processuais, conforme a legislação vigente e eventual determinação judicial."}, {"id": "p078", "t": "Cláusula 34º - É vedado ao LOCATÁRIO ceder, transferir ou sublocar, total ou parcialmente, o imóvel objeto deste contrato, bem como emprestá-lo a terceiros, sem prévia autorização expressa e por escrito do LOCADOR, nos termos do artigo 13 da Lei nº 8.245/91."}, {"id": "p079", "t": "Parágrafo único: Em caso de separação de fato, separação judicial, divórcio ou dissolução da união estável do LOCATÁRIO, a locação prosseguirá automaticamente com aquele que permanecer no imóvel, observadas as disposições do artigo 12 da Lei nº 8.245/91, inclusive quanto à comunicação ao LOCADOR e ao FIADOR."}, {"id": "p080", "t": "Cláusula 35º - Caso o LOCADOR pretenda vender o imóvel durante a vigência da locação, deverá assegurar ao LOCATÁRIO o direito de preferência para aquisição, em igualdade de condições com terceiros, mediante comunicação formal contendo todas as condições do negócio, inclusive preço, forma de pagamento e demais informações pertinentes, nos termos dos artigos 27 e seguintes da Lei nº 8.245/91."}, {"id": "p081", "t": "Parágrafo único: O LOCATÁRIO terá o prazo legal de 30 (trinta) dias, contado do recebimento da comunicação, para manifestar sua aceitação integral e inequívoca da proposta. Caso não exerça o direito de preferência, deverá permitir visitas de interessados, mediante prévio agendamento e em horários previamente acordados."}, {"id": "p084", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p085", "t": "Cláusula 38º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da estrutura e partes integrantes do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p088", "t": "Cláusula 39º - O descumprimento da obrigação de contratação ou renovação do seguro contra incêndio, após notificação para regularização, poderá caracterizar infração contratual, sujeitando o LOCATÁRIO às medidas legais e contratuais cabíveis."}, {"id": "p089", "t": "Cláusula 40º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro incêndio individual."}, {"id": "p091", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p093", "t": "Cláusula 43º - O tratamento de dados pessoais para finalidades adicionais, não abrangidas pelas hipóteses legais previstas na cláusula anterior, dependerá da existência de base legal adequada, inclusive consentimento específico do titular, quando necessário, assegurados os direitos previstos na Lei nº 13.709/2018."}, {"id": "p094", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p095", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p096", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p097", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p098", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p099", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p100", "t": "[[ASSINATURAS]]"}]$inter$::jsonb, 'Rascunho só intermediação, revisão jurídica pendente');
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, $inter$caucao_dinheiro_intermediacao$inter$, 1, $inter$Caução em dinheiro — só intermediação$inter$, $inter$residencial$inter$, $inter$caucao$inter$, NULL, $inter$CAUÇÃO$inter$, $inter$[{"id": "p001", "t": "QUADRO RESUMO: Locador(es); Locatário(a); Imóvel; Destinação da Locação; Prazo da Locação; Valor e Vencimento do Aluguel; Primeiro Aluguel; Reajuste e Indexador; Encargos Locatícios; Contas de Consumo; Transferência de Titularidade; Garantia Locatícia; Inadimplência; Vistoria Inicial; Contestação da Vistoria; Conservação e Manutenção do Imóvel; Benfeitorias e Modificações; Vistoria Final e Revistoria; Rescisão e Multa Contratual; Desocupação e Aviso Prévio; Seguro Incêndio; Sublocação/Cessão; Preferência na Compra do Imóvel; LGPD; Disposições Gerais; Foro."}, {"id": "p002", "t": "PRÊAMBULO"}, {"id": "p003", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p004", "t": "[[LOCADOR]]"}, {"id": "p005", "t": "[[LOCATARIO]]"}, {"id": "p007", "t": "GARANTIA LOCATÍCIA: As partes convencionam que a garantia locatícia é representada pela importância de R$ [CAUCAO_VALOR] ([CAUCAO_VALOR_EXTENSO]), equivalente a [CAUCAO_MESES] aluguéis do início da locação, que deverá ser pago através de [CAUCAO_FORMA], favorecido, [CAUCAO_FAVORECIDO]. Valor este a ser devolvido no final da locação, corrigido pelo índice da POUPANÇA do período."}, {"id": "p008", "t": "Cláusula 1º - Ao término do prazo de locação, desde que cumpridas pelo LOCATÁRIO, todas as obrigações decorrentes deste contrato, inclusive, a desocupação do imóvel e a entrega das chaves, sem a existência de quaisquer débitos ou de reparos a serem realizados pelo LOCATÁRIO para com o LOCADOR, convencionam, ainda as partes, que o valor da caução em dinheiro será devolvida, bem como suas correções através do índice da Caderneta de Poupança, em benefício do LOCATÁRIO por ocasião do levantamento da soma respectiva, ao final do vínculo locatário. Para tanto, deverá ser apresentado, documento rescisório da locação, firmado pelo LOCADOR e LOCATÁRIO, com o reconhecimento de firmas das assinaturas ou realizada através de assinatura eletrônica."}, {"id": "p010", "t": "Cláusula 3º - A hipótese do LOCATÁRIO contestar o valor apresentado e ajuizar a competente ação cautelar de prestação de contas, correrão por sua conta todas as despesas consequentes, inclusive custas e honorários advocatícios."}, {"id": "p011", "t": "[[OBJETO]]"}, {"id": "p012", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p013", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p014", "t": "O imóvel identificado neste instrumento destina-se exclusivamente à MORADIA do LOCATÁRIO e dos moradores expressamente identificados neste contrato, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "residencial"}, {"id": "p015", "t": "O imóvel identificado neste instrumento destina-se exclusivamente ao uso COMERCIAL do LOCATÁRIO, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "comercial", "adaptado": true}, {"id": "p016", "t": "[[PRAZO]]"}, {"id": "p017", "t": "Cláusula 4º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), devendo ser pago pelo LOCATÁRIO até o dia [DIA_VENCIMENTO] de cada mês, conforme as condições estabelecidas neste instrumento."}, {"id": "p018", "t": "Cláusula 5º - O primeiro aluguel vencerá 30 (trinta) dias após a efetiva entrega das chaves ao LOCATÁRIO. Os aluguéis subsequentes vencerão todo dia [DIA_VENCIMENTO] de cada mês, observando-se, quando necessário, o cálculo proporcional dos períodos de ocupação, a fim de evitar cobrança em duplicidade."}, {"id": "p019", "t": "[[ADICIONAIS]]"}, {"id": "p020", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p021", "t": "Além do aluguel mensal, serão de responsabilidade do LOCATÁRIO os encargos locatícios expressamente atribuídos a ele neste contrato, os quais serão devidos a partir da efetiva entrega das chaves, observadas as disposições legais e contratuais aplicáveis."}, {"id": "p022", "t": "Cláusula 6º - O atraso no pagamento do aluguel ou de quaisquer encargos locatícios acarretará a incidência de multa moratória de 10% (dez por cento) sobre o valor devido, acrescida de juros de mora de 1% (um por cento) ao mês, calculados proporcionalmente aos dias de atraso, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p025", "t": "Cláusula 9º - O inadimplemento do aluguel ou de quaisquer encargos locatícios na data do vencimento constituirá o LOCATÁRIO em mora, independentemente de notificação, facultando ao LOCADOR adotar as medidas judiciais e extrajudiciais cabíveis, inclusive ação de despejo e cobrança, nos termos da Lei nº 8.245/91, sem prejuízo dos encargos moratórios previstos neste contrato."}, {"id": "p027", "t": "Cláusula 11º – O LOCATÁRIO declara estar ciente de que o inadimplemento das obrigações financeiras decorrentes deste contrato poderá ensejar o protesto dos respectivos débitos, observadas as exigências legais aplicáveis."}, {"id": "p028", "t": "Cláusula 12º - O inadimplemento das obrigações locatícias poderá ensejar a adoção das medidas judiciais cabíveis, bem como a comunicação dos débitos aos órgãos de proteção ao crédito, desde que observados os requisitos legais, inclusive quanto à legitimidade, exatidão e atualização das informações fornecidas."}, {"id": "p029", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p030", "t": "O valor do aluguel será reajustado anualmente, respeitado o intervalo mínimo permitido pela legislação vigente, mediante aplicação do índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), ou de outro índice oficial que venha a substituí-lo em caso de sua extinção, observadas as disposições legais aplicáveis."}, {"id": "p033", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p034", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p035", "t": "Cláusula 15º – O locatário obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das de ELERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p036", "t": "DO DESCUMPRIMENTO E DAS PROVIDÊNCIAS ADMINISTRATIVAS:"}, {"id": "p040", "t": "Cláusula 17º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE"}, {"id": "p041", "t": "VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso para HABITAÇÃO.", "dest": "residencial"}, {"id": "p042", "t": "VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso COMERCIAL.", "dest": "comercial", "adaptado": true}, {"id": "p044", "t": "Cláusula 19º - Fica permitido ao LOCATÁRIO realizar pequenos furos nas paredes do imóvel para a fixação de quadros, espelhos, suportes e objetos similares, desde que não comprometam a estrutura, as instalações hidráulicas ou elétricas. Fica expressamente vedada a realização de furos em azulejos, revestimentos cerâmicos e áreas impermeabilizadas, salvo mediante autorização prévia e por escrito do LOCADOR. Ao término da locação, o LOCATÁRIO deverá providenciar a adequada reparação dos furos realizados nas paredes, recompondo a pintura e o acabamento quando necessário, restituindo o imóvel nas condições em que o recebeu, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p045", "t": "Cláusula 20º - O LOCATÁRIO deverá devolver o imóvel com a pintura nas mesmas condições em que o recebeu, conforme descrito no laudo de vistoria inicial, responsabilizando-se pela reparação de manchas, riscos, alterações de cores, descascamentos ou danos decorrentes de uso inadequado ou de sua responsabilidade, ressalvado o desgaste natural decorrente do uso regular do imóvel."}, {"id": "p046", "t": "Cláusula 21º - O LOCATÁRIO deverá zelar pela conservação dos pisos, azulejos, armários, acessórios e demais itens que integram o imóvel, responsabilizando-se pelos danos que causar por ação, omissão ou uso inadequado, devendo providenciar o reparo ou a substituição dos itens danificados por outros de padrão, qualidade e características equivalentes aos originalmente existentes, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p048", "t": "Cláusula 23º - O LOCATÁRIO deverá verificar a tensão elétrica disponível nos pontos de energia do imóvel antes de conectar seus equipamentos e aparelhos eletrônicos, responsabilizando-se pelos danos decorrentes da utilização inadequada ou incompatível com a tensão disponível, desde que as instalações tenham sido entregues em condições regulares de funcionamento e que as informações disponíveis tenham sido corretamente fornecidas."}, {"id": "p049", "t": "Cláusula 24º - O LOCATÁRIO não poderá realizar modificações, alterações ou benfeitorias no imóvel sem prévia autorização, por escrito, do LOCADOR. Salvo ajuste expresso em contrário, as benfeitorias realizadas, ainda que autorizadas, incorporar-se-ão ao imóvel, sem direito de indenização ou retenção pelo LOCATÁRIO, nos termos do artigo 35 da Lei nº 8.245/91 e da Súmula 335 do STJ, ressalvadas as obrigações legais do LOCADOR relativas à conservação, segurança e habitabilidade do imóvel."}, {"id": "p050", "t": "Cláusula 25º - Compete ao LOCATÁRIO realizar os reparos e serviços de manutenção decorrentes do uso regular do imóvel, bem como reparar os danos causados por si, seus moradores, visitantes ou terceiros sob sua responsabilidade. Compete ao LOCADOR realizar os reparos relativos a vícios anteriores à locação, problemas estruturais e defeitos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, desde que não decorrentes de ação ou omissão do LOCATÁRIO."}, {"id": "p052", "t": "Cláusula 26º - O LOCADOR poderá exigir que o LOCATÁRIO remova modificações ou benfeitorias realizadas sem autorização prévia e por escrito, quando necessário à recomposição do imóvel às condições originais, correndo as despesas correspondentes por conta do LOCATÁRIO, desde que decorrentes de sua responsabilidade."}, {"id": "p053", "t": "Cláusula 27º - Ao término da locação, será realizada vistoria final para verificar as condições de conservação do imóvel, mediante comparação com o laudo de vistoria inicial, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p054", "t": "Parágrafo 1º: Caso sejam constatados danos ou irregularidades de responsabilidade do LOCATÁRIO, este será comunicado para que possa providenciar os respectivos reparos no prazo de 05 (cinco) dias corridos, ou outro prazo acordado entre as partes, sem prejuízo da cobrança de eventuais valores necessários à recomposição do imóvel."}, {"id": "p055", "t": "Parágrafo 2º: Caso o LOCATÁRIO não realize os reparos de sua responsabilidade, o LOCADOR poderá providenciá-los e exigir o ressarcimento dos respectivos custos, mediante apresentação dos comprovantes pertinentes, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p056", "t": "Parágrafo 3º: A vistoria final será realizada sem custo para o LOCATÁRIO. Caso seja necessária nova vistoria para verificação dos reparos executados, poderá ser cobrada taxa de revistoria no valor de R$ 150,00 (cento e cinquenta reais), desde que previamente informada e relacionada à necessidade de nova verificação de pendências de responsabilidade do LOCATÁRIO."}, {"id": "p057", "t": "Parágrafo 4º: A existência de danos ou pendências apontadas na vistoria não impedirá o recebimento das chaves nem a formalização da devolução do imóvel, permanecendo assegurado ao LOCADOR o direito de exigir o ressarcimento dos prejuízos comprovadamente atribuíveis ao LOCATÁRIO."}, {"id": "p058", "t": "Cláusula 28º - O LOCATÁRIO permitirá que o LOCADOR ou seu representante devidamente autorizado examine ou vistori? o imóvel, mediante prévio agendamento e comunicação com antecedência mínima de 48 (quarenta e oito) horas, em dia e horário previamente acordados entre as partes, respeitado o direito à privacidade e ao uso pacífico do imóvel."}, {"id": "p059", "t": "Cláusula 29º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade residencial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "residencial"}, {"id": "p060", "t": "Cláusula 29º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade comercial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "comercial", "adaptado": true}, {"id": "p061", "t": "Cláusula 30º - Em caso de desapropriação do imóvel, a locação será extinta, ficando o LOCADOR desobrigado das obrigações futuras decorrentes deste contrato, ressalvados os direitos do LOCATÁRIO de pleitear eventual indenização diretamente perante o poder público desapropriante, quando legalmente cabível."}, {"id": "p062", "t": "Cláusula 31º - O LOCATÁRIO obriga-se a respeitar as normas de convivência, os direitos de vizinhança, as regras condominiais e a legislação vigente, abstendo-se de praticar atos que comprometam a segurança, a tranquilidade, a higiene ou o sossego dos demais moradores."}, {"id": "p063", "t": "Parágrafo primeiro: O descumprimento das obrigações legais ou contratuais poderá ensejar a aplicação das medidas cabíveis, inclusive rescisão da locação, conforme a natureza e a gravidade da infração, observadas as disposições da Lei nº 8.245/91."}, {"id": "p064", "t": "Parágrafo segundo: Fica estipulada multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente à época da infração, aplicável em caso de descumprimento contratual que justifique sua incidência, observados os critérios de proporcionalidade, a natureza da obrigação descumprida e a legislação vigente."}, {"id": "p065", "t": "Parágrafo terceiro: Na hipótese de devolução antecipada do imóvel por iniciativa do LOCATÁRIO durante o prazo determinado deste contrato, será devida multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente, calculada proporcionalmente ao período restante do contrato, conforme o artigo 4º da Lei nº 8.245/91."}, {"id": "p066", "t": "Cláusula 32º - Fica o LOCATÁRIO isento do pagamento de multa contratual por desocupação voluntária do imóvel após o 12º (décimo segundo) mês de locação, tendo, porém, a obrigação de avisar por escrito com, no mínimo, 30 (trinta) dias de antecedência, ficando responsável pelo pagamento do aluguel e dos acessórios locatícios durante o período de aviso.", "cond": "isencao_multa"}, {"id": "p067", "t": "Parágrafo primeiro: A isenção da multa rescisória apenas caberá em benefício do LOCATÁRIO, caso esteja quite com todas as demais obrigações previstas neste instrumento. Caso contrário fica estipulada a multa contratual compensatória proporcionalmente ao período de cumprimento do contrato, em conformidade com a nova redação do artigo 4º, atribuída pela Lei no 12.112/2009, na qual incorrerá o LOCATÁRIO na hipótese de devolução do imóvel antes do prazo pactuado.", "cond": "isencao_multa"}, {"id": "p069", "t": "Cláusula 34º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p071", "t": "Parágrafo único: Na ausência do aviso prévio previsto nesta cláusula, o LOCADOR poderá exigir quantia correspondente a 01 (um) mês de aluguel e encargos vigentes na data da rescisão, conforme disposto no artigo 6º, parágrafo único, da Lei nº 8.245/91."}, {"id": "p072", "t": "Cláusula 36º - Fica eleito o foro da comarca onde se localiza o imóvel objeto desta locação para dirimir quaisquer controvérsias decorrentes deste contrato, ressalvadas as hipóteses legais de competência absoluta."}, {"id": "p073", "t": "Parágrafo único: Em caso de demanda judicial decorrente do descumprimento das obrigações contratuais, as partes responderão pelas custas e despesas processuais, conforme a legislação vigente e eventual determinação judicial."}, {"id": "p074", "t": "Cláusula 37º - É vedado ao LOCATÁRIO ceder, transferir ou sublocar, total ou parcialmente, o imóvel objeto deste contrato, bem como emprestá-lo a terceiros, sem prévia autorização expressa e por escrito do LOCADOR, nos termos do artigo 13 da Lei nº 8.245/91."}, {"id": "p075", "t": "Cláusula 38º - Caso o LOCADOR pretenda vender o imóvel durante a vigência da locação, deverá assegurar ao LOCATÁRIO o direito de preferência para aquisição, em igualdade de condições com terceiros, mediante comunicação formal contendo todas as condições do negócio, inclusive preço, forma de pagamento e demais informações pertinentes, nos termos dos artigos 27 e seguintes da Lei nº 8.245/91."}, {"id": "p076", "t": "Parágrafo único: O LOCATÁRIO terá o prazo legal de 30 (trinta) dias, contado do recebimento da comunicação, para manifestar sua aceitação integral e inequívoca da proposta. Caso não exerça o direito de preferência, deverá permitir visitas de interessados, mediante prévio agendamento e em horários previamente acordados."}, {"id": "p079", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p080", "t": "Cláusula 41º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da estrutura e partes integrantes do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p083", "t": "Cláusula 42º - O descumprimento da obrigação de contratação ou renovação do seguro contra incêndio, após notificação para regularização, poderá caracterizar infração contratual, sujeitando o LOCATÁRIO às medidas legais e contratuais cabíveis."}, {"id": "p084", "t": "Cláusula 43º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro incêndio individual."}, {"id": "p086", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p088", "t": "Cláusula 46º - O tratamento de dados pessoais para finalidades adicionais, não abrangidas pelas hipóteses legais previstas na cláusula anterior, dependerá da existência de base legal adequada, inclusive consentimento específico do titular, quando necessário, assegurados os direitos previstos na Lei nº 13.709/2018."}, {"id": "p089", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p090", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p091", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p092", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p093", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p094", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p095", "t": "[[ASSINATURAS]]"}]$inter$::jsonb, 'Rascunho só intermediação, revisão jurídica pendente');
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, $inter$caucao_imovel_intermediacao$inter$, 1, $inter$Caução de imóvel (caucionamento) — só intermediação$inter$, $inter$comercial$inter$, $inter$caucao$inter$, NULL, $inter$CAUCIONAMENTO DE IMÓVEL$inter$, $inter$[{"id": "p001", "t": "PRÊAMBULO"}, {"id": "p002", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p003", "t": "[[LOCADOR]]"}, {"id": "p004", "t": "[[LOCATARIO]]"}, {"id": "p006", "t": "GARANTIA LOCATÍCIA: CAUCIONAMENTO – Comparece também neste ato na qualidade de CAUCIONANTE: [CAUCIONANTE_QUALIFICACAO]"}, {"id": "p007", "t": "Parágrafo primeiro: A CAUCIONANTE qualificada neste contrato, dá como CAUÇÃO, na forma do artigo 37, inciso I e 38, § 1º da Lei 8.245/91, o imóvel assim descrito: [CAUCAO_IMOVEL_DESCRICAO] Registro de Imóveis de [CAUCAO_IMOVEL_CARTORIO] – Matrícula [CAUCAO_IMOVEL_MATRICULA]"}, {"id": "p008", "t": "Parágrafo segundo: A CAUCIONANTE autoriza expressamente o registro e averbação deste contrato junto ao Cartório de Imóveis competente, bem como o caucionamento do imóvel descrito na cláusula acima, através do presente contrato, em favor da locação do imóvel situado na [IMOVEL_ENDERECO] inclusive requerendo a LOCADORA, perante o cartório competente a averbação de tal garantia na matrícula do imóvel."}, {"id": "p010", "t": "[[OBJETO]]"}, {"id": "p011", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p012", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p013", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso COMERCIAL dos LOCATÁRIO (S).", "dest": "comercial"}, {"id": "p014", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso de MORADIA dos LOCATÁRIO (S).", "dest": "residencial", "adaptado": true}, {"id": "p015", "t": "[[PRAZO]]"}, {"id": "p016", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), conforme acordado entre as partes e o(a) LOCATÁRIO(A) se compromete a pagar pontualmente até o dia [DIA_VENCIMENTO] de cada mês subsequente."}, {"id": "p017", "t": "Cláusula 2º - O primeiro aluguel será pago 30 dias após a data de entrega das chaves e os aluguéis subsequentes, serão pagos na data de vencimento fixada neste documento."}, {"id": "p018", "t": "[[ADICIONAIS]]"}, {"id": "p019", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p020", "t": "O valor do aluguel pode ser acrescido de acessórios locatícios e encargos, se aplicável, conforme estipulado neste contrato. O cômputo desses encargos será a partir da posse da chave e serão cobrados juntamente com o aluguel na data estabelecida."}, {"id": "p021", "t": "Cláusula 3º - O aluguel mensal deve ser pago juntamente com os demais encargos, em moeda corrente nacional, em seu vencimento, ficando em caso contrário acrescidos de multa de 10% (dez por cento) do seu valor, mais juros de 1% (um por cento) ao mês, mais a correção monetária prevista em lei, a título de penalidade contratual, sem prejuízo da exigibilidade das demais correções estipuladas."}, {"id": "p024", "t": "Cláusula 6º - O inadimplemento do aluguel ou de quaisquer encargos locatícios na data do vencimento constituirá o LOCATÁRIO em mora, facultando ao LOCADOR promover as medidas judiciais e extrajudiciais cabíveis, inclusive ação de despejo e cobrança, nos termos da Lei nº 8.245/91, sem prejuízo da incidência da multa, juros, correção monetária, honorários advocatícios e demais penalidades previstas neste contrato."}, {"id": "p025", "t": "Cláusula 7º - O LOCATÁRIO(S) não terá direito a reter o pagamento do aluguel ou de qualquer outra quantia devida nos termos do presente contrato, sob a alegação de não terem sido atendidas exigências porventura solicitadas."}, {"id": "p026", "t": "Cláusula 8º – O LOCATÁRIO(S) fica ciente nesta data que, antes da propositura da ação de despejo por falta de pagamento do aluguel e encargos na data estipulada neste contrato, poderá haver o protesto, junto ao cartório competente."}, {"id": "p027", "t": "Cláusula 9º - Eventual inadimplência do aluguel e encargos por parte dos LOCATÁRIO (S), ensejará Ação Judicial, independente do prazo da mora, não se responsabilizando o LOCADOR(A) pela inclusão dos nomes dos devedores ou de seus Fiadores junto às entidades mantenedoras de bancos de proteção ao crédito, SERASA, SCPC etc."}, {"id": "p028", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p029", "t": "O valor do aluguel ora contratado sofrerá reajuste anualmente, em conformidade com a legislação específica. Entretanto, havendo alteração legal para nova periodicidade, esta será aplicada automaticamente, independentemente de confirmação das partes."}, {"id": "p030", "t": "INDEXADORES:"}, {"id": "p031", "t": "As partes de comum acordo estabelecem o índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), para a correção do aluguel, que será aplicado de acordo com a periodicidade acima. Havendo a extinção do mesmo, por determinação legal, as partes elegerão seu substituto imediatamente após a eventual extinção."}, {"id": "p034", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p035", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p036", "t": "Cláusula 12º – O LOCATÁRIO obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das contas de ÁGUA, ENERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade das referidas contas, por parte do LOCATÁRIO, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p037", "t": "Cláusula 13º – O descumprimento da obrigação prevista na CLÁUSULA 12º, autoriza o LOCADOR a reter as chaves até a devida apresentação dos respectivos comprovantes, sem que isso gere qualquer direito de indenização ou alegação de atraso na imissão da posse por parte do LOCATÁRIO."}, {"id": "p038", "t": "Cláusula 14º - O LOCATÁRIO declara receber, nesta data, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso COMERCIAL.", "dest": "comercial"}, {"id": "p039", "t": "Cláusula 14º - O LOCATÁRIO declara receber, nesta data, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso para HABITAÇÃO.", "dest": "residencial", "adaptado": true}, {"id": "p040", "t": "Cláusula 15º - Em caso de discordância do laudo de vistoria inicial, o LOCATÁRIO terá o prazo de 10 (dez) dias corridos para realizar sua contestação, mediante formalização por email ou notificação por correios. O silêncio será considerado concordância ao laudo inicial apresentado."}, {"id": "p041", "t": "Cláusula 16º - Fica terminantemente proibida a colocação de pregos e parafusos nas paredes ou executar furos nos azulejos. Caso o LOCATÁRIO necessite fixar armários de cozinha ou outros, deverá solicitar autorização por escrito ao LOCADOR, ocasião em que, uma vez autorizado, receberá uma cópia da planta hidráulica e elétrica do imóvel."}, {"id": "p042", "t": "Cláusula 17º - A repintura no imóvel ora locado por parte do LOCATÁRIO, deverá ser compatível com a tinta anterior, ou seja, nas mesmas cores e qualidade que foi entregue."}, {"id": "p043", "t": "Cláusula 18º - Os pisos, azulejos, armários modulados, ou qualquer item de acabamento do imóvel ora locado por parte do LOCATÁRIO, deverá ser entregue nas mesmas condições recebidas, ou seja, caso danifique algum desses itens, o mesmo deverá ser substituído pelo mesmo modelo, tamanho, marca e nas mesmas cores e qualidade que foi entregue."}, {"id": "p045", "t": "Cláusula 20º - Fica o LOCATÁRIO, responsável pela verificação da voltagem da corrente elétrica existente no imóvel, em todos os seus pontos, assumindo para si, eventuais danos em aparelhos e/ou equipamentos que sejam ligados sem a devida checagem."}, {"id": "p046", "t": "Cláusula 21º - O LOCATÁRIO não poderá realizar modificações, alterações ou introduzir benfeitorias no imóvel sem a prévia e expressa autorização por escrito do LOCADOR. As benfeitorias realizadas, ainda que autorizadas, incorporar-se-ão ao imóvel, não assistindo ao LOCATÁRIO direito de retenção ou indenização, inclusive quanto às benfeitorias úteis e voluptuárias, nos termos da Lei nº 8.245/91, salvo disposição expressa em contrário firmada entre as partes. As benfeitorias expressamente autorizadas pelo LOCADOR para realização pelo LOCATÁRIO encontram-se descritas em cláusula adicional deste contrato, devendo ser observadas as condições nela estabelecidas."}, {"id": "p047", "t": "Cláusula 22º - São de responsabilidade do LOCATÁRIO as obras de manutenção do imóvel, cabendo exclusivamente ao LOCADOR aquelas que importem na estrutura e segurança dele, nos termos da legislação vigente. I): Sendo necessária a realização de qualquer obra ou manutenção por parte do LOCADOR, o LOCATÁRIO deverá notifica-lo para que no prazo de até 05 (cinco) dias úteis do recebimento da notificação, dar início aos reparos necessários. Não sendo realizados, fica desde já autorizado o LOCATÁRIO a realizar três orçamentos e providenciar a realização dos reparos que importem a estrutura ou segurança do imóvel e cobrá-los do LOCADOR pelo menor preço orçado."}, {"id": "p048", "t": "Cláusula 23º - Fica ainda facultado ao LOCADOR quando lhe convier, exigir a remoção de benfeitorias introduzidas no imóvel sem sua autorização, correndo todas as despesas por conta do LOCATÁRIO."}, {"id": "p049", "t": "Cláusula 24º - Se na VISTORIA FINAL for constatado qualquer anormalidade no imóvel, o LOCATÁRIO será notificado no prazo de 05 (cinco) dias corridos, para reparar o defeito ou substituir as peças ou aparelhos defeituosos por sua conta e risco. Não atendida esta notificação, ficará facultado ao LOCADOR providenciar os serviços, cobrando do LOCATÁRIO, os valores gastos com material e mão de obra, além dos dias de aluguel necessários para tais reparos."}, {"id": "p050", "t": "Parágrafo único: As partes concordam que a vistoria final do imóvel será realizada sem qualquer custo para o LOCATÁRIO. Contudo, caso seja necessária a realização de uma revistoria, será cobrada uma taxa de R$ 120,00 (cento e vinte) reais para cobrir custos envolvidos."}, {"id": "p051", "t": "Cláusula 25º - O LOCATÁRIO desde já, faculta o LOCADOR, ou seu representante devidamente constituído, examinar ou vistoriar o imóvel locado, quando entender conveniente, com aviso de 48 (quarenta e oito) horas de antecedência."}, {"id": "p052", "t": "Cláusula 26º - O presente contrato poderá ser rescindido de pleno direito na hipótese de desapropriação, incêndio ou qualquer evento que torne o imóvel impróprio para uso e exija sua reconstrução, total ou parcial, impossibilitando sua utilização por período superior a 45 (quarenta e cinco) dias. Poderá, ainda, ser rescindido em caso de insolvência, recuperação judicial ou falência do LOCATÁRIO, quando aplicável, sem prejuízo das demais hipóteses previstas neste contrato e da incidência da multa contratual estabelecida na CLÁUSULA 28º."}, {"id": "p053", "t": "Cláusula 27º - No caso de desapropriação do imóvel locado, ficará o LOCADOR desobrigado por todas as cláusulas deste contrato, ressalvando-se ao LOCATÁRIO tão somente o direito de haver do poder público desapropriante a indenização a que porventura tenha direito."}, {"id": "p054", "t": "Cláusula 28º - O LOCATÁRIO é obrigado a respeitar os direitos de vizinhança, a lei do silêncio, regras de condomínio, evitando a prática de quaisquer atos que venham a perturbar a tranquilidade e as condições de saúde pública."}, {"id": "p055", "t": "Parágrafo primeiro: Ocorrerá também a rescisão do presente contrato se o LOCATÁRIO infringir obrigação legal ou cometer infração a qualquer uma das cláusulas do presente instrumento."}, {"id": "p056", "t": "Parágrafo segundo: Fica estipulada a multa contratual compensatória proporcional de 03 (três) vezes o valor do aluguel vigente da época da eventual infração, em benefício ao LOCADOR, sem prejuízo da exigibilidade das obrigações assumidas por este instrumento, podendo o LOCADOR, se assim lhe convier, considerar ao mesmo tempo rescindido o presente contrato de locação, independentemente de qualquer formalidade."}, {"id": "p058", "t": "Cláusula 30º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p060", "t": "Parágrafo único: Na ausência do aviso acima citado, o LOCADOR poderá exigir a quantia correspondente a 01 (um) mês de aluguel e encargos vigentes da data da rescisão, conforme autoriza o artigo 6º, da Lei no 8.245/91."}, {"id": "p061", "t": "Cláusula 32º - Fica eleito o foro da comarca onde se localiza o imóvel objeto da locação para dirimir quaisquer controvérsias oriundas deste contrato, com renúncia expressa de qualquer outro, por mais privilegiado que seja. Em qualquer procedimento judicial decorrente do descumprimento das obrigações assumidas neste contrato pelo LOCATÁRIO, este responderá pelo pagamento das custas processuais, despesas judiciais e honorários advocatícios, na forma da legislação vigente e conforme fixação judicial, quando cabível."}, {"id": "p062", "t": "Parágrafo único: Em qualquer procedimento judicial que o LOCATÁRIO der causa, correrão por sua conta além do principal, todas as custas e despesas oriundas desta medida e ainda, honorários advocatícios, mesmo em caso de purgação de mora, quando houver a propositura da ação ou logo após a distribuição da petição."}, {"id": "p063", "t": "Cláusula 33º - Não é permitida a transferência deste contrato, no todo ou em parte, a sublocação ou empréstimo do imóvel locado, sem prévio consentimento, por escrito do LOCADOR."}, {"id": "p064", "t": "Parágrafo único: Em caso de falecimento, separação de fato ou judicial, divórcio ou dissolução da união estável do LOCATÁRIO, esta locação prosseguirá automaticamente com seu cônjuge ou companheiro, este que permanecer no imóvel, nos termos da Lei."}, {"id": "p065", "t": "Cláusula 34º - Caso o imóvel seja colocado à venda, o LOCATÁRIO terá preferência na compra. Não havendo interesse no prazo de 30 (trinta) dias, o LOCATÁRIO deverá permitir e facilitar as visitas dos pretendentes ao mesmo, em conformidade com o artigo 27, da Lei no 8.245/91."}, {"id": "p068", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p069", "t": "Cláusula 37º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da parte perecível do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p072", "t": "Cláusula 38º - A falta do pagamento do seguro por parte do LOCATÁRIO, constituirá infração passível de rescisão do presente instrumento, independente da incidência da multa infracional prevista em contrato."}, {"id": "p073", "t": "Cláusula 39º - Tratando-se de unidade integrante de condomínio edilício, não será aceita a apólice coletiva contratada pelo condomínio em substituição ao seguro contra incêndio previsto na CLÁUSULA 37º, permanecendo o LOCATÁRIO obrigado ao cumprimento integral da obrigação contratual."}, {"id": "p075", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p078", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p079", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p080", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p081", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p082", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p083", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p084", "t": "[[ASSINATURAS]]"}]$inter$::jsonb, 'Rascunho só intermediação, revisão jurídica pendente');
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, $inter$seguro_porto_intermediacao$inter$, 1, $inter$Seguro-fiança Porto Seguro — só intermediação$inter$, $inter$residencial$inter$, $inter$seguro_fianca$inter$, $inter$porto$inter$, $inter$SEGURO FIANÇA PORTO SEGURO$inter$, $inter$[{"id": "p001", "t": "QUADRO RESUMO: Locador(es); Locatário(a); Imóvel; Destinação da Locação; Prazo da Locação; Valor e Vencimento do Aluguel; Primeiro Aluguel; Reajuste e Indexador; Encargos Locatícios; Contas de Consumo; Transferência de Titularidade; Garantia Locatícia; Inadimplência; Vistoria Inicial; Contestação da Vistoria; Conservação e Manutenção do Imóvel; Benfeitorias e Modificações; Vistoria Final e Revistoria; Rescisão e Multa Contratual; Desocupação e Aviso Prévio; Seguro Incêndio; Sublocação/Cessão; Preferência na Compra do Imóvel; LGPD; Disposições Gerais; Foro."}, {"id": "p002", "t": "PRÊAMBULO"}, {"id": "p003", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p004", "t": "[[LOCADOR]]"}, {"id": "p005", "t": "[[LOCATARIO]]"}, {"id": "p007", "t": "GARANTIA LOCATÍCIA: O seguro de Fiança Locatícia contratado pelo LOCADOR junto a PORTO SEGURO CIA. DE SEGUROS GERAIS, em que a vigência inicial será a data de protocolo da proposta ou data distinta acordada entre as partes e a vigência final será a data do término do contrato de locação, garantirá está locação, nos termos do inciso III, do artigo 37 da Lei do Inquilinato, mediante pagamento de prêmio, ressalvadas as exceções previstas nas condições gerais.", "trava": true}, {"id": "p008", "t": "A PORTO SEGURO CIA. DE SEGUROS GERAIS, disponibiliza a possibilidade de contratação de produtos com condições diferentes em relação ao Limite Máximo de Garantia (LMG).", "trava": true}, {"id": "p009", "t": "No SEGURO FIANÇA LOCATÍCIA TRADICIONAL, o LMG é a soma dos limites máximos de indenização (LMI) das coberturas contratadas. No SEGURO FIANÇA LOCATÍCIA ESSENCIAL, o LMG da apólice é igual ao LMI da cobertura de ALUGUEL. Quando contratada apenas a Cobertura Básica - Não Pagamento de Aluguéis, o Limite Máximo de Garantia da apólice será igual ao Limite Máximo de Indenização desta mesma cobertura. Quando houver a contratação de coberturas adicionais, o Limite Máximo de Garantia da apólice será menor que a soma dos Limites Máximos de Indenização das coberturas contratadas. São de conhecimento do LOCADOR e LOCATÁRIO as Condições Gerais do seguro de Fiança Locatícia, sendo que para a contratação da apólice, LOCADOR e LOCATÁRIO definiram previamente, mediante acordo, a seguradora, o corretor de seguros e os limites da apólice.", "trava": true}, {"id": "p010", "t": "Para efeito desta garantia, LOCADOR e LOCATÁRIO acordam que os prêmios iniciais e renovações do seguro da fiança locatícia, calculados conforme NORMAS VIGENTES, serão pagos pelo LOCATÁRIOS,de acordo com o inciso XI, do artigo 23 da lei do inquilinato, sob pena de rescisão desta locação, com o consequente despejo e cancelamento da apólice.", "trava": true}, {"id": "p011", "t": "Na hipótese de inadimplência do LOCATÁRIO, o LOCADOR poderá efetuar o pagamento dos prêmios, para que a apólice permaneça vigente. Em caso de prorrogação do contrato de locação, com alterações que influenciam nas condições iniciais de aceitação, a seguradora se reservará ao direito de realizar nova análise do risco.", "trava": true}, {"id": "p012", "t": "LOCADOR e LOCATÁRIO declaram que até a data da contratação do seguro, todas as obrigações contratuais foram cumpridas pelas partes, tendo o LOCATÁRIO adimplido pontualmente todos os aluguéis e encargos da locação. Declaram ainda que não há sinistro a reclamar, quanto a aluguéis e encargos, bem como estão cientes que não haverá cobertura securitária para os aluguéis e encargos vencidos e vincendos, caso seja identificado que o primeiro inadimplemento tenha ocorrido antes da contratação do seguro, ficando a seguradora, desobrigada e isenta de toda e qualquer responsabilidade, ainda que haja reclamação futura de inadimplência anterior a data de contratação do seguro A apólice garantirá exclusivamente as coberturas especificadas na proposta de seguro.", "trava": true}, {"id": "p013", "t": "Eventuais débitos decorrentes do presente contrato, não pagos pelo LOCATÁRIO após regularmente instados a tanto serão comunicados às entidades mantenedoras de bancos de dados de proteção ao crédito (Serasa, SPC, etc.), quer pelos Locadores, quer pela Seguradora, quer pela Administradora. Tais débitos incluem todas as despesas com as medidas judiciais cabíveis. Notificações em geral, inclusive sobre eventuais débitos decorrentes do presente contrato poderão ser realizadas ao(s) LOCATÁRIO(S), via e-mail.", "trava": true}, {"id": "p014", "t": "Cláusula 1º - Pagamento do prêmio pelo locador/proprietário", "trava": true}, {"id": "p015", "t": "O seguro de Fiança Locatícia contratado pelo(s) LOCADOR(ES) junto a PORTO SEGURO CIA. DE SEGUROS GERAIS, em que a vigência inicial será a data de protocolo da proposta ou data distinta acordada entre as partes e a vigência final será a data do término do contrato de locação, garantirá está locação, nos termos do inciso III, do artigo 37 da Lei do Inquilinato, mediante pagamento de prêmio, ressalvadas as exceções previstas nas condições gerais.", "trava": true}, {"id": "p016", "t": "A PORTO SEGURO CIA. DE SEGUROS GERAIS, disponibiliza a possibilidade de contratação de produtos com condições diferentes em relação ao Limite Máximo de Garantia (LMG).", "trava": true}, {"id": "p017", "t": "No SEGURO FIANÇA LOCATÍCIA TRADICIONAL, o LMG é a soma dos limites máximos de indenização (LMI) das coberturas contratadas No SEGURO FIANÇA LOCATÍCIA ESSENCIAL, o LMG da apólice é igual ao LMI da cobertura de ALUGUEL. Quando contratada apenas a Cobertura Básica - Não Pagamento de Aluguéis, o Limite Máximo de Garantia da apólice será igual ao Limite Máximo de Indenização desta mesma cobertura. Quando houver a contratação de coberturas adicionais, o Limite Máximo de Garantia da apólice será menor que a soma dos Limites Máximos de Indenização das coberturas contratadas.", "trava": true}, {"id": "p018", "t": "São de conhecimento do(s) LOCADOR(ES) e LOCATÁRIO(S) as Condições Gerais do seguro de Fiança Locatícia, sendo que para a contratação da apólice, LOCADOR(ES) e LOCATÁRIO(S) definiram previamente, mediante acordo, a seguradora, o corretor de seguros e os limites da apólice. Para efeito desta garantia, os prêmios iniciais e renovações do seguro da fiança locatícia, calculados conforme NORMAS VIGENTES, serão pagos pelo LOCADOR(ES).", "trava": true}, {"id": "p019", "t": "Em caso de prorrogação do contrato de locação, com alterações que influenciam nas condições iniciais de aceitação, a seguradora se reservará ao direito de realizar nova análise do risco.", "trava": true}, {"id": "p020", "t": "LOCADOR(ES) e LOCATÁRIO (S) declaram que até a data da contratação do seguro, todas as obrigações contratuais foram cumpridas pelas partes, tendo o LOCATÁRIO(S) adimplido pontualmente todos os aluguéis e encargos da locação. Declaram ainda que não há sinistro a reclamar, quanto a aluguéis e encargos, bem como estão cientes que não haverá cobertura securitária para os aluguéis e encargos vencidos e vincendos, caso seja identificado que o primeiro inadimplemento tenha ocorrido antes da contratação do seguro, ficando a seguradora, desobrigada e isenta de toda e qualquer responsabilidade, ainda que haja reclamação futura de inadimplência anterior a data de contratação do seguro.", "trava": true}, {"id": "p021", "t": "A apólice garantirá exclusivamente as coberturas especificadas na proposta de seguro. Eventuais débitos decorrentes do presente contrato, não pagos pelo(s) LOCATÁRIO(S) após regularmente instados a tanto serão comunicados às entidades mantenedoras de bancos de dados de proteção ao crédito (Serasa, SPC, etc.), quer pelos Locadores, quer pela Seguradora. Tais débitos incluem todas as despesas com as medidas judiciais cabíveis.", "trava": true}, {"id": "p022", "t": "Notificações em geral, inclusive sobre eventuais débitos decorrentes do presente contrato poderão ser realizadas ao(s) LOCATÁRIO(S), via e-mail.", "trava": true}, {"id": "p023", "t": "Cláusula 2º - (quando contratada a cobertura adicional de danos ao imóvel)", "trava": true}, {"id": "p024", "t": "LOCADOR (es) e LOCATÁRIO(s) declara(m) que o Laudo de Vistoria Inicial, com descrição do estado do imóvel, foi elaborado antes da posse do imóvel, bem como o(s) LOCATÁRIO(s) concorda(m) com o conteúdo do laudo. O(s) LOCATÁRIO(s) declaram para todos os fins e efeitos de direito, que recebe(m) o imóvel locado no estado em que se encontra de conservação e uso, identificado no Relatório referente ao estado de uso e conservação do imóvel o qual é parte integrante deste contrato, assinado por todos os contratantes, obrigando-se e comprometendo-se a devolvê-lo nesse estado, independentemente de qualquer aviso ou notificação prévia, e qualquer que seja o motivo de devolução, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei, além da obrigação de indenizar por danos ou prejuízos decorrentes da inobservância dessa obrigação, salvo as deteriorações decorrentes do uso normal do imóvel.", "trava": true}, {"id": "p025", "t": "Cláusula 3º - (quando contratada a cobertura adicional de pintura interna)", "trava": true}, {"id": "p026", "t": "LOCADOR (es) e LOCATÁRIO(s) declara(m) que o Laudo de Vistoria Inicial, com descrição do estado[ do imóvel, foi elaborado antes da posse do imóvel, bem como o(s) LOCATÁRIO(s) concorda(m) com o conteúdo do laudo. Declara(m) o(s) locatário(s), para todos os fins e efeitos de direito, que recebe(m) o imóvel locado com Pintura Interna NOVA, e assim obriga-se, ao final da locação, a pintá-lo e devolvê-lo no mesmo estado em que recebeu, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei. O(s) locatário(s) declara(m) ainda estar ciente de que, não devolvendo o imóvel pintado internamente, a Seguradora indenizará o locador pelo ônus da pintura, e terá direito de reaver o valor que tiver sido pago. O Segurado poderá comunicar o Sinistro a Porto Seguro no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p027", "t": "Cláusula 4º - (quando contratada a cobertura adicional de pintura externa)", "trava": true}, {"id": "p028", "t": "LOCADOR e LOCATÁRIO declara que o Laudo de Vistoria Inicial, com descrição do estado do imóvel, foi elaborado antes da posse do imóvel, bem como o LOCATÁRIO concorda com o conteúdo do laudo. Declara(m) o(s) locatário(s), para todos os fins e efeitos de direito, que recebe(m) o imóvel locado com Pintura Externa NOVA, e assim obriga-se, ao final da locação, a pintá-lo e devolvê-lo no mesmo estado que recebeu, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei. O(s) locatário(s) declara(m) ainda estar ciente de que não devolvendo o imóvel pintado externamente, a Seguradora indenizará o locador pelo ônus da pintura, e terá direito de reaver o valor que tiver sido pago. O Segurado poderá comunicar o Sinistro a PORTO SEGURO no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p029", "t": "APÓLICE: [APOLICE_REFERENCIA]"}, {"id": "p030", "t": "[[OBJETO]]"}, {"id": "p031", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p032", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p033", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso de MORADIA dos LOCATÁRIO (S).", "dest": "residencial"}, {"id": "p034", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso COMERCIAL dos LOCATÁRIO (S).", "dest": "comercial", "adaptado": true}, {"id": "p035", "t": "[[PRAZO]]"}, {"id": "p036", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), conforme acordado entre as partes e o(a) LOCATÁRIO(A) se compromete a pagar pontualmente até o dia [DIA_VENCIMENTO] de cada mês subsequente."}, {"id": "p037", "t": "Cláusula 2º - O primeiro aluguel será pago 30 dias após a data de entrega das chaves e os aluguéis subsequentes, serão pagos na data de vencimento fixada neste documento."}, {"id": "p038", "t": "[[ADICIONAIS]]"}, {"id": "p039", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p040", "t": "O valor do aluguel pode ser acrescido de acessórios locatícios e encargos, se aplicável, conforme estipulado neste contrato. O cômputo desses encargos será a partir da posse da chave e serão cobrados juntamente com o aluguel na data estabelecida."}, {"id": "p041", "t": "Cláusula 3º - O aluguel mensal deve ser pago juntamente com os demais encargos, em moeda corrente nacional, em seu vencimento, ficando em caso contrário acrescidos de multa de 10% (dez por cento) do seu valor, mais juros de 1% (um por cento) ao mês, mais a correção monetária prevista em lei, a título de penalidade contratual, sem prejuízo da exigibilidade das demais correções estipuladas."}, {"id": "p044", "t": "Cláusula 6º - Além das penalidades previstas na CLÁUSULA 3º, a falta de pagamento do aluguel na data estipulada poderá acarretar a rescisão do presente contrato, após 15 (quinze) dias da data do vencimento, ficando o LOCATÁRIO(S) responsável pela multa prevista na CLÁUSULA 28º - Parágrafo segundo do presente contrato, pelas despesas processuais e honorários advocatícios."}, {"id": "p045", "t": "Cláusula 7º - O LOCATÁRIO(S) não terá direito a reter o pagamento do aluguel ou de qualquer outra quantia devida nos termos do presente contrato, sob a alegação de não terem sido atendidas exigências porventura solicitadas."}, {"id": "p046", "t": "Cláusula 8º – O LOCATÁRIO(S) fica ciente nesta data que, antes da propositura da ação de despejo por falta de pagamento do aluguel e encargos na data estipulada neste contrato, poderá haver o protesto, junto ao cartório competente."}, {"id": "p047", "t": "Cláusula 9º - Eventual inadimplência do aluguel e encargos por parte dos LOCATÁRIO (S), ensejará Ação Judicial, independente do prazo da mora, não se responsabilizando o LOCADOR(A) pela inclusão dos nomes dos devedores ou de seus Fiadores junto às entidades mantenedoras de bancos de proteção ao crédito, SERASA, SCPC etc."}, {"id": "p048", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p049", "t": "O valor do aluguel ora contratado sofrerá reajuste anualmente, em conformidade com a legislação específica. Entretanto, havendo alteração legal para nova periodicidade, esta será aplicada automaticamente, independentemente de confirmação das partes."}, {"id": "p050", "t": "INDEXADORES:"}, {"id": "p051", "t": "As partes de comum acordo estabelecem o índice IGPM (Índice Geral de Preço de Mercado), para a correção do aluguel, que será aplicado de acordo com a periodicidade acima. Havendo a extinção do mesmo, por determinação legal, as partes elegerão seu substituto imediatamente após a eventual extinção."}, {"id": "p054", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p055", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p056", "t": "Cláusula 12º – O LOCATÁRIO obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das contas de ÁGUA, ENERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade das referidas contas, por parte do LOCATÁRIO, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p057", "t": "Cláusula 13º – O descumprimento da obrigação prevista na CLÁUSULA 12º, autoriza o LOCADOR a reter as chaves até a devida apresentação dos respectivos comprovantes, sem que isso gere qualquer direito de indenização ou alegação de atraso na imissão da posse por parte do LOCATÁRIO."}, {"id": "p058", "t": "Cláusula 14º - O LOCATÁRIO recebendo na data da assinatura deste contrato, o respectivo laudo de vistoria inicial, cujo documento aponta o estado de conservação do imóvel, declara concordar que o imóvel tem como finalidade, o uso de HABITAÇÃO, considerando inclusive suas instalações ELÉTRICAS, HIDRÁULICAS e SANITÁRIAS. Obriga-se o LOCATÁRIO a manter o imóvel assim como consta em LAUDO DE VISTORIA INICIAL, de forma a tudo restituir na mais perfeita ordem e no mesmo estado de conservação, higiene e funcionamento, quando findo ou rescindido o presente contrato, de modo que possa ser imediatamente ocupado pelo LOCADOR ou por quem este indicar, sem que isso dependa de qualquer conserto, reparação, etc. O LOCADOR será responsável pelos problemas estruturais, caso seja necessario.", "dest": "residencial"}, {"id": "p059", "t": "Cláusula 14º - O LOCATÁRIO recebendo na data da assinatura deste contrato, o respectivo laudo de vistoria inicial, cujo documento aponta o estado de conservação do imóvel, declara concordar que o imóvel tem como finalidade, o uso COMERCIAL, considerando inclusive suas instalações ELÉTRICAS, HIDRÁULICAS e SANITÁRIAS. Obriga-se o LOCATÁRIO a manter o imóvel assim como consta em LAUDO DE VISTORIA INICIAL, de forma a tudo restituir na mais perfeita ordem e no mesmo estado de conservação, higiene e funcionamento, quando findo ou rescindido o presente contrato, de modo que possa ser imediatamente ocupado pelo LOCADOR ou por quem este indicar, sem que isso dependa de qualquer conserto, reparação, etc. O LOCADOR será responsável pelos problemas estruturais, caso seja necessario.", "dest": "comercial", "adaptado": true}, {"id": "p060", "t": "Cláusula 15º - Em caso de discordância do laudo de vistoria inicial, o LOCATÁRIO terá o prazo de 10 (dez) dias corridos para realizar sua contestação, mediante formalização por email ou notificação por correios. O silêncio será considerado concordância ao laudo inicial apresentado."}, {"id": "p061", "t": "Cláusula 16º - Fica terminantemente proibida a colocação de pregos e parafusos nas paredes ou executar furos nos azulejos. Caso o LOCATÁRIO necessite fixar armários de cozinha ou outros, deverá solicitar autorização por escrito ao LOCADOR, ocasião em que, uma vez autorizado, receberá uma cópia da planta hidráulica e elétrica do imóvel."}, {"id": "p062", "t": "Cláusula 17º - A repintura no imóvel ora locado por parte do LOCATÁRIO, deverá ser compatível com a tinta anterior, ou seja, nas mesmas cores e qualidade que foi entregue."}, {"id": "p063", "t": "Cláusula 18º - Os pisos, azulejos, armários modulados, ou qualquer item de acabamento do imóvel ora locado por parte do LOCATÁRIO, deverá ser entregue nas mesmas condições recebidas, ou seja, caso danifique algum desses itens, o mesmo deverá ser substituído pelo mesmo modelo, tamanho, marca e nas mesmas cores e qualidade que foi entregue."}, {"id": "p065", "t": "Cláusula 20º - Fica o LOCATÁRIO, responsável pela verificação da voltagem da corrente elétrica existente no imóvel, em todos os seus pontos, assumindo para si, eventuais danos em aparelhos e/ou equipamentos que sejam ligados sem a devida checagem."}, {"id": "p066", "t": "Cláusula 21º - O LOCATÁRIO não poderá fazer modificações ou transformações no imóvel locado, nem introduzir quaisquer benfeitorias, sem que haja prévio aviso e consentimento por escrito do LOCADOR. Realizado benfeitorias, desde que tenham sido com o consentimento expresso da LOCADOR, essas ficarão incorporadas ao imóvel sem qualquer direito ao LOCATÁRIO, de retenção ou indenização, ao término da locação."}, {"id": "p067", "t": "Cláusula 22º - São de responsabilidade do LOCATÁRIO as obras de manutenção do imóvel, cabendo exclusivamente ao LOCADOR aquelas que importem na estrutura e segurança dele, nos termos da legislação vigente. I): Sendo necessária a realização de qualquer obra ou manutenção por parte do LOCADOR, o LOCATÁRIO deverá notifica-lo para que no prazo de até 05 (cinco) dias úteis do recebimento da notificação, dar início aos reparos necessários. Não sendo realizados, fica desde já autorizado o LOCATÁRIO a realizar três orçamentos e providenciar a realização dos reparos que importem a estrutura ou segurança do imóvel e cobrá-los do LOCADOR pelo menor preço orçado."}, {"id": "p068", "t": "Cláusula 23º - Fica ainda facultado ao LOCADOR quando lhe convier, exigir a remoção de benfeitorias introduzidas no imóvel sem sua autorização, correndo todas as despesas por conta do LOCATÁRIO."}, {"id": "p069", "t": "Cláusula 24º - Se na VISTORIA FINAL for constatado qualquer anormalidade no imóvel, o LOCATÁRIO será notificado no prazo de 05 (cinco) dias corridos, para reparar o defeito ou substituir as peças ou aparelhos defeituosos por sua conta e risco. Não atendida esta notificação, ficará facultado ao LOCADOR providenciar os serviços, cobrando do LOCATÁRIO, os valores gastos com material e mão de obra, além dos dias de aluguel necessários para tais reparos, sem prejuízo da cobrança por eventuais perdas e danos que a LOCADORA vier a incorrer."}, {"id": "p070", "t": "Parágrafo único: As partes concordam que a vistoria final do imóvel será realizada sem qualquer custo para o LOCATÁRIO. Contudo, caso seja necessária a realização de uma revistoria, será cobrada do LOCATÁRIO uma taxa de R$ 120,00 (cento e vinte) reais para cobrir custos envolvidos."}, {"id": "p071", "t": "Cláusula 25º - O LOCATÁRIO desde já, faculta o LOCADOR, ou seu representante devidamente constituído, examinar ou vistoriar o imóvel locado, quando entender conveniente, com aviso de 48 (quarenta e oito) horas de antecedência."}, {"id": "p072", "t": "Cláusula 26º - Ocorrerá a rescisão do presente contrato de pleno direito, no caso de desapropriação, incêndio ou acidente que sujeite o imóvel locado a obras que importem na sua reconstrução ainda que parcial, que impeçam o seu uso por mais de 45 (quarenta e cinco) dias, ou, ainda, no caso de se verificar ou ocorrer a insolvência, recuperação judicial ou falência do LOCATÁRIO, ou se forem verificados atos desabonadores, de ordem civil ou criminal de sua parte, sem prejuízo das demais cláusulas contratuais e da responsabilidade da multa contratual estipulada na CLÁUSULA 28º, que alcançará também os Fiadores (se houver)."}, {"id": "p073", "t": "Cláusula 27º - No caso de desapropriação do imóvel locado, ficará o LOCADOR desobrigado por todas as cláusulas deste contrato, ressalvando-se ao LOCATÁRIO tão somente o direito de haver do poder público desapropriante a indenização a que porventura tenha direito."}, {"id": "p074", "t": "Cláusula 28º - O LOCATÁRIO é obrigado a respeitar os direitos de vizinhança, a lei do silêncio, regras de condomínio, evitando a prática de quaisquer atos que venham a perturbar a tranquilidade e as condições de saúde pública."}, {"id": "p075", "t": "Parágrafo primeiro: Ocorrerá também a rescisão do presente contrato se o LOCATÁRIO infringir obrigação legal ou cometer infração a qualquer uma das cláusulas do presente instrumento."}, {"id": "p076", "t": "Parágrafo segundo: Fica estipulada a multa contratual não compensatória proporcional de 03 (três) vezes o valor do aluguel vigente da época da eventual infração, em benefício ao LOCADOR, sem prejuízo da exigibilidade das p e r da s e da n o s , a l é m d a s obrigações assumidas por este instrumento, podendo o LOCADOR, se assim lhe convier, considerar ao mesmo tempo rescindido o presente contrato de locação, independentemente de qualquer formalidade."}, {"id": "p078", "t": "Cláusula 30º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p080", "t": "Parágrafo único: Na ausência do aviso acima citado, o LOCADOR poderá exigir a quantia correspondente a 01 (um) mês de aluguel e encargos vigentes da data da rescisão, conforme autoriza o artigo 6º, da Lei no 8.245/91."}, {"id": "p081", "t": "Cláusula 32º - Tudo quanto for devido em razão deste contrato, notadamente os aluguéis mensais e seus acessórios, será cobrado por ação judicial apropriada no FORO TERRITORIAL DO IMÓVEL, com expressa renúncia de qualquer outro, por mais privilegiado que seja, o qual desde já fica eleito pelos contratantes como seu domicílio, para que exercitem e cumpram todos os direitos e obrigações decorrentes do presente instrumento."}, {"id": "p082", "t": "Parágrafo único: Em qualquer procedimento judicial que o LOCATÁRIO der causa, correrão por sua conta além do principal, todas as custas e despesas oriundas desta medida e ainda, honorários advocatícios, mesmo em caso de purgação de mora, quando houver a propositura da ação ou logo após a distribuição da petição."}, {"id": "p083", "t": "Cláusula 33º - Não é permitida a transferência deste contrato, no todo ou em parte, a sublocação ou empréstimo do imóvel locado, sem prévio consentimento, por escrito do LOCADOR."}, {"id": "p084", "t": "Parágrafo único: Em caso de falecimento, separação de fato ou judicial, divórcio ou dissolução da união estável do LOCATÁRIO, esta locação prosseguirá automaticamente com seu cônjuge ou companheiro, este que permanecer no imóvel, nos termos da Lei."}, {"id": "p085", "t": "Cláusula 34º - Caso o imóvel seja colocado à venda, o LOCATÁRIO terá preferência na compra. Não havendo interesse no prazo de 30 (trinta) dias, o LOCATÁRIO deverá permitir e facilitar as visitas dos pretendentes ao mesmo, em conformidade com o artigo 27, da Lei no 8.245/91."}, {"id": "p088", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p089", "t": "Cláusula 37º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da parte perecível do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p092", "t": "Cláusula 38º - A falta do pagamento do seguro por parte do LOCATÁRIO, constituirá infração passível de rescisão do presente instrumento, independente da incidência da multa infracional prevista em contrato."}, {"id": "p093", "t": "Cláusula 39º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro mencionado na CLÁUSULA 38º."}, {"id": "p095", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p098", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p099", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p100", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IGPM (Índice Geral de Preço de Mercado); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p101", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p102", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p103", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p104", "t": "[[ASSINATURAS]]"}]$inter$::jsonb, 'Rascunho só intermediação, revisão jurídica pendente');
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, $inter$seguro_pottencial_intermediacao$inter$, 1, $inter$Seguro-fiança Pottencial — só intermediação$inter$, $inter$residencial$inter$, $inter$seguro_fianca$inter$, $inter$pottencial$inter$, $inter$SEGURO FIANÇA POTTENCIAL$inter$, $inter$[{"id": "p001", "t": "QUADRO RESUMO: Locador(es); Locatário(a); Imóvel; Destinação da Locação; Prazo da Locação; Valor e Vencimento do Aluguel; Primeiro Aluguel; Reajuste e Indexador; Encargos Locatícios; Contas de Consumo; Transferência de Titularidade; Garantia Locatícia; Inadimplência; Vistoria Inicial; Contestação da Vistoria; Conservação e Manutenção do Imóvel; Benfeitorias e Modificações; Vistoria Final e Revistoria; Rescisão e Multa Contratual; Desocupação e Aviso Prévio; Seguro Incêndio; Sublocação/Cessão; Preferência na Compra do Imóvel; LGPD; Disposições Gerais; Foro."}, {"id": "p002", "t": "PRÊAMBULO"}, {"id": "p003", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p004", "t": "[[LOCADOR]]"}, {"id": "p005", "t": "[[LOCATARIO]]"}, {"id": "p007", "t": "GARANTIA LOCATÍCIA: SEGURO POTTENCIAL ALUGUEL: As Partes anuem com a emissão de seguro fiança locatícia para garantia do presente contrato, nos termos do art. 37, III da Lei nº 8.245/1991 (Lei de Locações), a ser contratado pelo(a) LOCATÁRIO(A), junto à Pottencial Seguradora S.A., tendo como Segurado o LOCADOR e declaram ter negociado e anuído com a indicação do corretor de seguros, as coberturas e limites de indenização contratados, cujos termos e condições do contrato de seguro estão disponíveis para consulta através do link https://pottencial.com.br/certidoes-legais/condicoesgerais/.", "trava": true}, {"id": "p008", "t": "O seguro estará vigente pelo período previsto na apólice emitida. Ocorrendo prorrogação de prazo do presente contrato de locação com alteração das condições anteriormente estabelecidas entre as partes, mediante formalização de aditivo ou em razão de prorrogação por prazo indeterminado por força de lei ou ato normativo, a Seguradora deverá ser comunicada para reanálise de aceitação do risco.", "trava": true}, {"id": "p010", "t": "Inadimplência - Em caso de inadimplência do LOCATÁRIO(A), a SEGURADORA concederá prazo ao LOCADOR(A) para pagamento do prêmio, nos termos previstos nas Condições Gerais do seguro, sob pena de cancelamento do seguro e rescisão desta locação por infração contratual, com o consequente despejo.", "trava": true}, {"id": "p012", "t": "Pagamento de indenizações e Sub-rogação. Em caso de pagamento de qualquer indenização securitária, a SEGURADORA sub-rogar-se-á automaticamente no direito do LOCADOR(A) de cobrar os débitos em aberto em face do(a) LOCATÁRIO(A).", "trava": true}, {"id": "p013", "t": "Restrição Financeira. Eventuais débitos decorrentes do presente contrato ou do contrato de seguro não pagos pelo LOCATÁRIO(A) serão comunicados às entidades mantenedoras de bancos de dados de proteção ao crédito (Serasa, SPC, etc.), quer pelo LOCADOR(A), quer pela SEGURADORA, inclusive de todas as despesas havidas com as medidas judiciais cabíveis.", "trava": true}, {"id": "p014", "t": "Locatário Solidário – Havendo mais de um LOCATÁRIO(A) para exercer os direitos e dar cumprimento às obrigações desse contrato, ao firmarem esta locação, os LOCATÁRIOS(AS) declaram-se solidários entre si e constituem-se reciprocamente PROCURADORES, conferindose mutuamente poderes especiais para receber citações, notificações e intimações, confessar, desistir, e assinar tudo quanto se tornar necessário, transigir em juízo ou fora dele, fazer acordos, firmar compromissos judiciais ou extrajudiciais, receber e dar quitação, no âmbito deste contrato.", "trava": true}, {"id": "p015", "t": "Cobertura adicional de Multa Rescisória (contratação opcional) – Em caso de contratação desta cobertura adicional, o(a) LOCATÁRIO(A) reconhece que a entrega antecipada do imóvel antes da vigência final do contrato de locação configura quebra contratual, estando, portanto, obrigado ao pagamento de multa por rescisão que, caso não adimplida, poderá ensejar o pagamento da indenização securitária pela SEGURADORA. O(A) LOCATÁRIO(A) declara, ainda, estar ciente de que, não realizando o pagamento da multa prevista ao(a) LOCADOR(A), a SEGURADORA efetuará a indenização, com consequente pedido de ressarcimento em face do(a) LOCATÁRIO(A). O Segurado deverá comunicar o Sinistro à Pottencial no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p016", "t": "Cobertura adicional de Danos ao Imóvel (contratação opcional) – Em caso de contratação desta cobertura adicional, o(a) LOCATÁRIO(A) declara para todos os fins e efeitos de direito, que recebe o imóvel locado no estado em que se encontra de conservação e uso, identificado no Laudo (Relatório) de Vistoria Inicial assinado por todos os contratantes, o qual é parte integrante deste contrato, obrigando-se e comprometendo-se o(a) LOCATÁRIO(A) a devolvê-lo nesse estado, independentemente de qualquer aviso ou notificação prévia e qualquer que seja o motivo de devolução, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei, além da obrigação de indenizar por danos ou prejuízos decorrentes da inobservância dessa obrigação, salvo as deteriorações decorrentes do uso normal do imóvel. O(A) LOCATÁRIO(A) declara, ainda, estar ciente de que, não realizando o pagamento dos prejuízos ao(a) LOCADOR(A), a SEGURADORA efetuará a indenização nos termos dos limites e condições contratuais do seguro, com consequente pedido de ressarcimento em face do(a) LOCATÁRIO(A). LOCADOR(A) e LOCATÁRIO(A) declaram que o Laudo (Relatório) de Vistoria Inicial com descrição do estado do imóvel foi elaborado antes da posse do imóvel, estando de acordo com todo o conteúdo do laudo. É imprescindível e obrigatória a apresentação do Relatório do Estado do Uso de Conservação do imóvel, assinado pelo Locador(a) e Locatário(a) como condição para pagamento de indenização pela SEGURADORA. O Segurado deverá comunicar o Sinistro à Pottencial o no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p017", "t": "Cobertura adicional de Pintura Interna Nova (contratação opcional) – Caso contratada esta cobertura, declara o(a) LOCATÁRIO (A), para todos os fins e efeitos de direito, que recebe o imóvel locado com Pintura Interna NOVA e, assim, obriga-se, ao final da locação, a pintá-lo e devolvê-lo no mesmo estado em que recebeu, sob pena de arcar com os valores devidos ao(a) LOCADOR(A) para realização de nova pintura. O(A) LOCATÁRIO(A) declara ainda estar ciente de que, não devolvendo o imóvel pintado internamente, e estando a respectiva cobertura contratada na proposta de seguro, a SEGURADORA indenizará o(a) LOCADOR(A) pelos prejuízos havidos com a nova pintura, e terá direito de reaver o valor que tiver sido pago, nos termos dos limites e condições contratuais do seguro, em face do(a) LOCATÁRIO(A). O Segurado deverá comunicar o Sinistro à Pottencial no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p018", "t": "Cobertura adicional de Pintura Externa Nova (cobertura opcional) – A cobertura é exclusiva para imóveis residenciais e não residenciais (casas para fins comerciais), na qual o locatário ocupa a área global do imóvel alugado. Declara o(a) LOCATÁRIO(A), para todos os fins e efeitos de direito, que recebe o imóvel locado com Pintura Externa NOVA, e assim obriga-se, ao final da locação, a pintá-lo e devolvê-lo no mesmo estado que recebeu, sob pena de arcar com os valores devidos ao(a) LOCADOR(A) para realização de nova pintura O(A) LOCATÁRIO(A) declara ainda estar ciente de que, não devolvendo o imóvel pintado internamente, e estando a respectiva cobertura contratada na proposta de seguro, a SEGURADORA indenizará o(a) LOCADOR(A) pelos prejuízos havidos com a nova pintura, e terá direito de reaver o valor que tiver sido pago, nos termos dos limites e condições contratuais do seguro, em face do(a) LOCATÁRIO(A). O(A) Segurado(a) deverá comunicar o Sinistro a Pottencial no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p019", "t": "APÓLICE: [APOLICE_REFERENCIA]"}, {"id": "p020", "t": "[[OBJETO]]"}, {"id": "p021", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p022", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p023", "t": "O imóvel identificado neste instrumento destina-se exclusivamente à MORADIA do LOCATÁRIO e dos moradores expressamente identificados neste contrato, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "residencial"}, {"id": "p024", "t": "O imóvel identificado neste instrumento destina-se exclusivamente ao uso COMERCIAL do LOCATÁRIO, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "comercial", "adaptado": true}, {"id": "p025", "t": "[[PRAZO]]"}, {"id": "p026", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), devendo ser pago pelo LOCATÁRIO até o dia [DIA_VENCIMENTO] de cada mês, conforme as condições estabelecidas neste instrumento."}, {"id": "p027", "t": "Cláusula 2º - O primeiro aluguel vencerá 30 (trinta) dias após a efetiva entrega das chaves ao LOCATÁRIO. Os aluguéis subsequentes vencerão todo dia [DIA_VENCIMENTO] de cada mês, observando-se, quando necessário, o cálculo proporcional dos períodos de ocupação, a fim de evitar cobrança em duplicidade."}, {"id": "p028", "t": "[[ADICIONAIS]]"}, {"id": "p029", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p030", "t": "Além do aluguel mensal, serão de responsabilidade do LOCATÁRIO os encargos locatícios expressamente atribuídos a ele neste contrato, os quais serão devidos a partir da efetiva entrega das chaves, observadas as disposições legais e contratuais aplicáveis."}, {"id": "p031", "t": "Cláusula 3º - O atraso no pagamento do aluguel ou de quaisquer encargos locatícios acarretará a incidência de multa moratória de 10% (dez por cento) sobre o valor devido, acrescida de juros de mora de 1% (um por cento) ao mês, calculados proporcionalmente aos dias de atraso, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p034", "t": "Cláusula 6º - O inadimplemento do aluguel ou de quaisquer encargos locatícios na data do vencimento constituirá o LOCATÁRIO em mora, independentemente de notificação, facultando ao LOCADOR adotar as medidas judiciais e extrajudiciais cabíveis, inclusive ação de despejo e cobrança, nos termos da Lei nº 8.245/91, sem prejuízo dos encargos moratórios previstos neste contrato."}, {"id": "p036", "t": "Cláusula 8º – O LOCATÁRIO declara estar ciente de que o inadimplemento das obrigações financeiras decorrentes deste contrato poderá ensejar o protesto dos respectivos débitos, observadas as exigências legais aplicáveis."}, {"id": "p037", "t": "Cláusula 9º - O inadimplemento das obrigações locatícias poderá ensejar a adoção das medidas judiciais cabíveis, bem como a comunicação dos débitos aos órgãos de proteção ao crédito, desde que observados os requisitos legais, inclusive quanto à legitimidade, exatidão e atualização das informações fornecidas."}, {"id": "p038", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p039", "t": "O valor do aluguel será reajustado anualmente, respeitado o intervalo mínimo permitido pela legislação vigente, mediante aplicação do índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), ou de outro índice oficial que venha a substituí-lo em caso de sua extinção, observadas as disposições legais aplicáveis."}, {"id": "p042", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p043", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p044", "t": "Cláusula 12º – O locatário obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das de ÁGUA, ELERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p045", "t": "DO DESCUMPRIMENTO E DAS PROVIDÊNCIAS ADMINISTRATIVAS:"}, {"id": "p049", "t": "Cláusula 14º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso para HABITAÇÃO.", "dest": "residencial"}, {"id": "p050", "t": "Cláusula 14º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso COMERCIAL.", "dest": "comercial", "adaptado": true}, {"id": "p052", "t": "Cláusula 16º - Fica permitido ao LOCATÁRIO realizar pequenos furos nas paredes do imóvel para a fixação de quadros, espelhos, suportes e objetos similares, desde que não comprometam a estrutura, as instalações hidráulicas ou elétricas. Fica expressamente vedada a realização de furos em azulejos, revestimentos cerâmicos e áreas impermeabilizadas, salvo mediante autorização prévia e por escrito do LOCADOR. Ao término da locação, o LOCATÁRIO deverá providenciar a adequada reparação dos furos realizados nas paredes, recompondo a pintura e o acabamento quando necessário, restituindo o imóvel nas condições em que o recebeu, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p053", "t": "Cláusula 17º - O LOCATÁRIO deverá devolver o imóvel com a pintura nas mesmas condições em que o recebeu, conforme descrito no laudo de vistoria inicial, responsabilizando-se pela reparação de manchas, riscos, alterações de cores, descascamentos ou danos decorrentes de uso inadequado ou de sua responsabilidade, ressalvado o desgaste natural decorrente do uso regular do imóvel."}, {"id": "p054", "t": "Cláusula 18º - O LOCATÁRIO deverá zelar pela conservação dos pisos, azulejos, armários, acessórios e demais itens que integram o imóvel, responsabilizando-se pelos danos que causar por ação, omissão ou uso inadequado, devendo providenciar o reparo ou a substituição dos itens danificados por outros de padrão, qualidade e características equivalentes aos originalmente existentes, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p056", "t": "Cláusula 20º - O LOCATÁRIO deverá verificar a tensão elétrica disponível nos pontos de energia do imóvel antes de conectar seus equipamentos e aparelhos eletrônicos, responsabilizando-se pelos danos decorrentes da utilização inadequada ou incompatível com a tensão disponível, desde que as instalações tenham sido entregues em condições regulares de funcionamento e que as informações disponíveis tenham sido corretamente fornecidas."}, {"id": "p057", "t": "Cláusula 21º - O LOCATÁRIO não poderá realizar modificações, alterações ou benfeitorias no imóvel sem prévia autorização, por escrito, do LOCADOR. Salvo ajuste expresso em contrário, as benfeitorias realizadas, ainda que autorizadas, incorporar-se-ão ao imóvel, sem direito de indenização ou retenção pelo LOCATÁRIO, nos termos do artigo 35 da Lei nº 8.245/91 e da Súmula 335 do STJ, ressalvadas as obrigações legais do LOCADOR relativas à conservação, segurança e habitabilidade do imóvel."}, {"id": "p058", "t": "Cláusula 22º - Compete ao LOCATÁRIO realizar os reparos e serviços de manutenção decorrentes do uso regular do imóvel, bem como reparar os danos causados por si, seus moradores, visitantes ou terceiros sob sua responsabilidade. Compete ao LOCADOR realizar os reparos relativos a vícios anteriores à locação, problemas estruturais e defeitos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, desde que não decorrentes de ação ou omissão do LOCATÁRIO."}, {"id": "p060", "t": "Cláusula 23º - O LOCADOR poderá exigir que o LOCATÁRIO remova modificações ou benfeitorias realizadas sem autorização prévia e por escrito, quando necessário à recomposição do imóvel às condições originais, correndo as despesas correspondentes por conta do LOCATÁRIO, desde que decorrentes de sua responsabilidade."}, {"id": "p061", "t": "Cláusula 24º - Ao término da locação, será realizada vistoria final para verificar as condições de conservação do imóvel, mediante comparação com o laudo de vistoria inicial, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p062", "t": "Parágrafo 1º: Caso sejam constatados danos ou irregularidades de responsabilidade do LOCATÁRIO, este será comunicado para que possa providenciar os respectivos reparos no prazo de 05 (cinco) dias corridos, ou outro prazo acordado entre as partes, sem prejuízo da cobrança de eventuais valores necessários à recomposição do imóvel."}, {"id": "p063", "t": "Parágrafo 2º: Caso o LOCATÁRIO não realize os reparos de sua responsabilidade, o LOCADOR poderá providenciá-los e exigir o ressarcimento dos respectivos custos, mediante apresentação dos comprovantes pertinentes, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p064", "t": "Parágrafo 3º: A vistoria final será realizada sem custo para o LOCATÁRIO. Caso seja necessária nova vistoria para verificação dos reparos executados, poderá ser cobrada taxa de revistoria no valor de R$ 150,00 (cento e cinquenta reais), desde que previamente informada e relacionada à necessidade de nova verificação de pendências de responsabilidade do LOCATÁRIO."}, {"id": "p065", "t": "Parágrafo 4º: A existência de danos ou pendências apontadas na vistoria não impedirá o recebimento das chaves nem a formalização da devolução do imóvel, permanecendo assegurado ao LOCADOR o direito de exigir o ressarcimento dos prejuízos comprovadamente atribuíveis ao LOCATÁRIO."}, {"id": "p066", "t": "Cláusula 25º - O LOCATÁRIO permitirá que o LOCADOR ou seu representante devidamente autorizado examine ou vistori? o imóvel, mediante prévio agendamento e comunicação com antecedência mínima de 48 (quarenta e oito) horas, em dia e horário previamente acordados entre as partes, respeitado o direito à privacidade e ao uso pacífico do imóvel."}, {"id": "p067", "t": "Cláusula 26º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade residencial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "residencial"}, {"id": "p068", "t": "Cláusula 26º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade comercial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "comercial", "adaptado": true}, {"id": "p069", "t": "Cláusula 27º - Em caso de desapropriação do imóvel, a locação será extinta, ficando o LOCADOR desobrigado das obrigações futuras decorrentes deste contrato, ressalvados os direitos do LOCATÁRIO de pleitear eventual indenização diretamente perante o poder público desapropriante, quando legalmente cabível."}, {"id": "p070", "t": "Cláusula 28º - O LOCATÁRIO obriga-se a respeitar as normas de convivência, os direitos de vizinhança, as regras condominiais e a legislação vigente, abstendo-se de praticar atos que comprometam a segurança, a tranquilidade, a higiene ou o sossego dos demais moradores."}, {"id": "p071", "t": "Parágrafo primeiro: O descumprimento das obrigações legais ou contratuais poderá ensejar a aplicação das medidas cabíveis, inclusive rescisão da locação, conforme a natureza e a gravidade da infração, observadas as disposições da Lei nº 8.245/91."}, {"id": "p072", "t": "Parágrafo segundo: Fica estipulada multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente à época da infração, aplicável em caso de descumprimento contratual que justifique sua incidência, observados os critérios de proporcionalidade, a natureza da obrigação descumprida e a legislação vigente."}, {"id": "p073", "t": "Parágrafo terceiro: Na hipótese de devolução antecipada do imóvel por iniciativa do LOCATÁRIO durante o prazo determinado deste contrato, será devida multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente, calculada proporcionalmente ao período restante do contrato, conforme o artigo 4º da Lei nº 8.245/91."}, {"id": "p074", "t": "Cláusula 29º - Fica o LOCATÁRIO isento do pagamento de multa contratual por desocupação voluntária do imóvel após o 12º (décimo segundo) mês de locação, tendo, porém, a obrigação de avisar por escrito com, no mínimo, 30 (trinta) dias de antecedência, ficando responsável pelo pagamento do aluguel e dos acessórios locatícios durante o período de aviso.", "cond": "isencao_multa"}, {"id": "p075", "t": "Parágrafo primeiro: A isenção da multa rescisória apenas caberá em benefício do LOCATÁRIO, caso esteja quite com todas as demais obrigações previstas neste instrumento. Caso contrário fica estipulada a multa contratual compensatória proporcionalmente ao período de cumprimento do contrato, em conformidade com a nova redação do artigo 4º, atribuída pela Lei no 12.112/2009, na qual incorrerá o LOCATÁRIO na hipótese de devolução do imóvel antes do prazo pactuado.", "cond": "isencao_multa"}, {"id": "p077", "t": "Cláusula 31º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p079", "t": "Parágrafo único: Na ausência do aviso prévio previsto nesta cláusula, o LOCADOR poderá exigir quantia correspondente a 01 (um) mês de aluguel e encargos vigentes na data da rescisão, conforme disposto no artigo 6º, parágrafo único, da Lei nº 8.245/91."}, {"id": "p080", "t": "Cláusula 33º - Fica eleito o foro da comarca onde se localiza o imóvel objeto desta locação para dirimir quaisquer controvérsias decorrentes deste contrato, ressalvadas as hipóteses legais de competência absoluta."}, {"id": "p081", "t": "Parágrafo único: Em caso de demanda judicial decorrente do descumprimento das obrigações contratuais, as partes responderão pelas custas e despesas processuais, conforme a legislação vigente e eventual determinação judicial."}, {"id": "p082", "t": "Cláusula 34º - É vedado ao LOCATÁRIO ceder, transferir ou sublocar, total ou parcialmente, o imóvel objeto deste contrato, bem como emprestá-lo a terceiros, sem prévia autorização expressa e por escrito do LOCADOR, nos termos do artigo 13 da Lei nº 8.245/91."}, {"id": "p083", "t": "Parágrafo único: Em caso de separação de fato, separação judicial, divórcio ou dissolução da união estável do LOCATÁRIO, a locação prosseguirá automaticamente com aquele que permanecer no imóvel, observadas as disposições do artigo 12 da Lei nº 8.245/91, inclusive quanto à comunicação ao LOCADOR e ao FIADOR."}, {"id": "p084", "t": "Cláusula 35º - Caso o LOCADOR pretenda vender o imóvel durante a vigência da locação, deverá assegurar ao LOCATÁRIO o direito de preferência para aquisição, em igualdade de condições com terceiros, mediante comunicação formal contendo todas as condições do negócio, inclusive preço, forma de pagamento e demais informações pertinentes, nos termos dos artigos 27 e seguintes da Lei nº 8.245/91."}, {"id": "p085", "t": "Parágrafo único: O LOCATÁRIO terá o prazo legal de 30 (trinta) dias, contado do recebimento da comunicação, para manifestar sua aceitação integral e inequívoca da proposta. Caso não exerça o direito de preferência, deverá permitir visitas de interessados, mediante prévio agendamento e em horários previamente acordados."}, {"id": "p088", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p089", "t": "Cláusula 38º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da estrutura e partes integrantes do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p092", "t": "Cláusula 39º - O descumprimento da obrigação de contratação ou renovação do seguro contra incêndio, após notificação para regularização, poderá caracterizar infração contratual, sujeitando o LOCATÁRIO às medidas legais e contratuais cabíveis."}, {"id": "p093", "t": "Cláusula 40º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro incêndio individual."}, {"id": "p095", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p097", "t": "Cláusula 43º - O tratamento de dados pessoais para finalidades adicionais, não abrangidas pelas hipóteses legais previstas na cláusula anterior, dependerá da existência de base legal adequada, inclusive consentimento específico do titular, quando necessário, assegurados os direitos previstos na Lei nº 13.709/2018."}, {"id": "p098", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p099", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p100", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p101", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p102", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p103", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p104", "t": "[[ASSINATURAS]]"}]$inter$::jsonb, 'Rascunho só intermediação, revisão jurídica pendente');
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, $inter$seguro_tokio_intermediacao$inter$, 1, $inter$Seguro-fiança Tokio Marine — só intermediação$inter$, $inter$residencial$inter$, $inter$seguro_fianca$inter$, $inter$tokio$inter$, $inter$TOKIO MARINE$inter$, $inter$[{"id": "p001", "t": "PRÊAMBULO"}, {"id": "p002", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p003", "t": "[[LOCADOR]]"}, {"id": "p004", "t": "[[LOCATARIO]]"}, {"id": "p006", "t": "GARANTIA LOCATICIA: CLÁUSULA OBRIGATÓRIA Nº 1 – DA GARANTIA LOCATÍCIA (Cláusula 1a – Obrigatória em todas as contratações) O seguro de Fiança Locatícia contratado pelo LOCADOR junto a TOKIO MARINE, garantirá esta locação, nos termos do inciso III, do artigo 37 da Lei do Inquilinato, mediante pagamento de prêmio, ressalvadas as exceções previstas nas condições gerais. São de conhecimento do LOCADOR e LOCATÁRIO(S) as Condições Gerais do seguro de Fiança Locatícia. Para efeito desta garanta, os prêmios iniciais e renovações, calculados conforme NORMAS VIGENTES, serão pagos pelo(s) Locatário(s), de acordo com o inciso XI, do artigo 23 da lei do inquilinato, sob pena de rescisão desta locação, com o consequente despejo e cancelamento da apólice. A apólice garantirá exclusivamente as coberturas especificadas na proposta de seguro. Eventuais débitos decorrentes do presente contrato, não pagos pelo(s) Locatário(s) após regularmente instados a tanto serão comunicados às entidades mantenedoras de bancos de dados de proteção ao crédito (Serasa, SPC, etc.), quer pelo Locador(a), quer pela Seguradora. Tais débitos incluem todas as despesas com as medidas judiciais cabíveis. Para exercer os direitos e dar cumprimento às obrigações desse contrato, os LOCATÁRIOS declaram-se solidários entre si e constituem-se reciprocamente PROCURADORES, conferindose mutuamente poderes especiais para receber citações, notificações e intimações, confessar, desistir, e assinar tudo quanto se tornar necessário, transigir em Juízo ou fora dele, fazer acordos, firmar compromissos judiciais ou extrajudiciais, receber e dar quitação.", "trava": true}, {"id": "p007", "t": "CLÁUSULA ESPECIAL Nº 2 – DANOS AO IMÓVEL (quando contratada a cobertura de danos ao imóvel) O locatário declara para todos os fins e efeitos de direito, que recebe o imóvel locado no estado em que se encontra de conservação e uso, identificado no Laudo de Vistoria Inicial o qual é parte integrante deste contrato, assinado por todos os contratantes, obrigando-se e comprometendo-se a devolvê-lo nesse estado, independentemente de qualquer aviso ou notificação prévia e qualquer que seja o motivo de devolução, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei, além da obrigação de indenizar por danos ou prejuízos decorrentes da inobservância dessa obrigação, salvo as deteriorações decorrentes do uso normal do imóvel.", "trava": true}, {"id": "p008", "t": "CLÁUSULA ESPECIAL Nº 3 – PINTURA INTERNA (Cláusula 3 – quando contratada a cobertura de pintura interna) Declara o locatário, para todos os fins e efeitos de direito, que recebe o imóvel locado com Pintura Interna NOVA, e assim obriga-se, ao final da locação, a pintá-lo e devolvê-lo no mesmo estado em que recebeu, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei. O locatário declara ainda estar ciente de que, não devolvendo o imóvel pintado internamente, a Seguradora indenizará o locador pelo ônus da pintura, e terá direito de reaver o valor que tiver sido pago. O Segurado deverá comunicar o Sinistro a TOKIO MARINE no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p009", "t": "CLÁUSULA ESPECIAL Nº 4 – PINTURA EXTERNA (Cláusula 4 – quando contratada a cobertura de pintura externa) Declara o locatário, para todos os fins e efeitos de direito, que recebe o imóvel locado com Pintura Externa NOVA, e assim obriga-se, ao final da locação, a pintá-lo e devolvê-lo no mesmo estado que recebeu, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei. O locatário declara ainda estar ciente de que não devolvendo o imóvel pintado externamente, a Seguradora indenizará o locador pelo ônus da pintura, e terá direito de reaver o valor que tiver sido pago. O Segurado deverá comunicar o Sinistro a TOKIO MARINE no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel. Esta cobertura é válida somente para imóveis residenciais e não residenciais do tipo “casa”, onde o locatário ocupa a totalidade do imóvel alugado.", "trava": true}, {"id": "p010", "t": "APÓLICE: [APOLICE_REFERENCIA]"}, {"id": "p011", "t": "[[OBJETO]]"}, {"id": "p012", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p013", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p014", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso de MORADIA dos LOCATÁRIO (S).", "dest": "residencial"}, {"id": "p015", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso COMERCIAL dos LOCATÁRIO (S).", "dest": "comercial", "adaptado": true}, {"id": "p016", "t": "[[PRAZO]]"}, {"id": "p017", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), conforme acordado entre as partes e o(a) LOCATÁRIO(A) se compromete a pagar pontualmente até o dia [DIA_VENCIMENTO] de cada mês subsequente."}, {"id": "p018", "t": "Cláusula 2º - O primeiro aluguel será pago 30 dias após a data de entrega das chaves e os aluguéis subsequentes, serão pagos na data de vencimento fixada neste documento."}, {"id": "p019", "t": "[[ADICIONAIS]]"}, {"id": "p020", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p021", "t": "O valor do aluguel pode ser acrescido de acessórios locatícios e encargos, se aplicável, conforme estipulado neste contrato. O cômputo desses encargos será a partir da posse da chave e serão cobrados juntamente com o aluguel na data estabelecida."}, {"id": "p022", "t": "Cláusula 3º - O aluguel mensal deve ser pago juntamente com os demais encargos, em moeda corrente nacional, em seu vencimento, ficando em caso contrário acrescidos de multa de 10% (dez por cento) do seu valor, mais juros de 1% (um por cento) ao mês, mais a correção monetária prevista em lei, a título de penalidade contratual, sem prejuízo da exigibilidade das demais correções estipuladas."}, {"id": "p025", "t": "Cláusula 6º - Além das penalidades previstas na CLÁUSULA 3º, a falta de pagamento do aluguel na data estipulada poderá acarretar a rescisão do presente contrato, após 15 (quinze) dias da data do vencimento, ficando o LOCATÁRIO(S) responsável pela multa prevista na CLÁUSULA 28º - Parágrafo segundo do presente contrato, pelas despesas processuais e honorários advocatícios."}, {"id": "p026", "t": "Cláusula 7º - O LOCATÁRIO(S) não terá direito a reter o pagamento do aluguel ou de qualquer outra quantia devida nos termos do presente contrato, sob a alegação de não terem sido atendidas exigências porventura solicitadas."}, {"id": "p027", "t": "Cláusula 8º – O LOCATÁRIO(S) fica ciente nesta data que, antes da propositura da ação de despejo por falta de pagamento do aluguel e encargos na data estipulada neste contrato, poderá haver o protesto, junto ao cartório competente."}, {"id": "p028", "t": "Cláusula 9º - Eventual inadimplência do aluguel e encargos por parte dos LOCATÁRIO (S), ensejará Ação Judicial, independente do prazo da mora, não se responsabilizando o LOCADOR(A) pela inclusão dos nomes dos devedores ou de seus Fiadores junto às entidades mantenedoras de bancos de proteção ao crédito, SERASA, SCPC etc."}, {"id": "p029", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p030", "t": "O valor do aluguel ora contratado sofrerá reajuste anualmente, em conformidade com a legislação específica. Entretanto, havendo alteração legal para nova periodicidade, esta será aplicada automaticamente, independentemente de confirmação das partes."}, {"id": "p031", "t": "INDEXADORES:"}, {"id": "p032", "t": "As partes de comum acordo estabelecem o índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), para a correção do aluguel, que será aplicado de acordo com a periodicidade acima. Havendo a extinção do mesmo, por determinação legal, as partes elegerão seu substituto imediatamente após a eventual extinção."}, {"id": "p035", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p036", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p037", "t": "Cláusula 12º - O LOCATÁRIA obriga-se a providenciar, junto às concessionárias competente, a transferência da titularidade das contas de ÁGUA, ENERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p038", "t": "DO DESCUMPRIMENTO E DAS PROVIDÊNCIAS ADMINISTRATIVAS:"}, {"id": "p042", "t": "Cláusula 15º - O LOCATÁRIO recebendo na data da assinatura deste contrato, o respectivo laudo de vistoria inicial, cujo documento aponta o estado de conservação do imóvel, declara concordar que o imóvel tem como finalidade, o uso de HABITAÇÃO, considerando inclusive suas instalações ELÉTRICAS, HIDRÁULICAS e SANITÁRIAS. Obriga-se o LOCATÁRIO a manter o imóvel assim como consta em LAUDO DE VISTORIA INICIAL, de forma a tudo restituir na mais perfeita ordem e no mesmo estado de conservação, higiene e funcionamento, quando findo ou rescindido o presente contrato, de modo que possa ser imediatamente ocupado pelo LOCADOR ou por quem este indicar, sem que isso dependa de qualquer conserto, reparação, etc. O LOCADOR será responsável pelos problemas estruturais, caso seja necessario.", "dest": "residencial"}, {"id": "p043", "t": "Cláusula 15º - O LOCATÁRIO recebendo na data da assinatura deste contrato, o respectivo laudo de vistoria inicial, cujo documento aponta o estado de conservação do imóvel, declara concordar que o imóvel tem como finalidade, o uso COMERCIAL, considerando inclusive suas instalações ELÉTRICAS, HIDRÁULICAS e SANITÁRIAS. Obriga-se o LOCATÁRIO a manter o imóvel assim como consta em LAUDO DE VISTORIA INICIAL, de forma a tudo restituir na mais perfeita ordem e no mesmo estado de conservação, higiene e funcionamento, quando findo ou rescindido o presente contrato, de modo que possa ser imediatamente ocupado pelo LOCADOR ou por quem este indicar, sem que isso dependa de qualquer conserto, reparação, etc. O LOCADOR será responsável pelos problemas estruturais, caso seja necessario.", "dest": "comercial", "adaptado": true}, {"id": "p044", "t": "Cláusula 16º - Em caso de discordância do laudo de vistoria inicial, o LOCATÁRIO terá o prazo de 10 (dez) dias corridos para realizar sua contestação, mediante formalização por email ou notificação por correios. O silêncio será considerado concordância ao laudo inicial apresentado."}, {"id": "p045", "t": "Cláusula 17º - Fica terminantemente proibida a colocação de pregos e parafusos nas paredes ou executar furos nos azulejos. Caso o LOCATÁRIO necessite fixar armários de cozinha ou outros, deverá solicitar autorização por escrito ao LOCADOR, ocasião em que, uma vez autorizado, receberá uma cópia da planta hidráulica e elétrica do imóvel."}, {"id": "p046", "t": "Cláusula 18º - A repintura no imóvel ora locado por parte do LOCATÁRIO, deverá ser compatível com a tinta anterior, ou seja, nas mesmas cores e qualidade que foi entregue."}, {"id": "p047", "t": "Cláusula 19º - Os pisos, azulejos, armários modulados, ou qualquer item de acabamento do imóvel ora locado por parte do LOCATÁRIO, deverá ser entregue nas mesmas condições recebidas, ou seja, caso danifique algum desses itens, o mesmo deverá ser substituído pelo mesmo modelo, tamanho, marca e nas mesmas cores e qualidade que foi entregue."}, {"id": "p049", "t": "Cláusula 21º - Fica o LOCATÁRIO, responsável pela verificação da voltagem da corrente elétrica existente no imóvel, em todos os seus pontos, assumindo para si, eventuais danos em aparelhos e/ou equipamentos que sejam ligados sem a devida checagem."}, {"id": "p050", "t": "Cláusula 22º - O LOCATÁRIO não poderá fazer modificações ou transformações no imóvel locado, nem introduzir quaisquer benfeitorias, sem que haja prévio aviso e consentimento por escrito do LOCADOR. Realizado benfeitorias, desde que tenham sido com o consentimento expresso da LOCADOR, essas ficarão incorporadas ao imóvel sem qualquer direito ao LOCATÁRIO, de retenção ou indenização, ao término da locação."}, {"id": "p051", "t": "Cláusula 23º - São de responsabilidade do LOCATÁRIO as obras de manutenção do imóvel, cabendo exclusivamente ao LOCADOR aquelas que importem na estrutura e segurança dele, nos termos da legislação vigente. I): Sendo necessária a realização de qualquer obra ou manutenção por parte do LOCADOR, o LOCATÁRIO deverá notifica-lo para que no prazo de até 05 (cinco) dias úteis do recebimento da notificação, dar início aos reparos necessários. Não sendo realizados, fica desde já autorizado o LOCATÁRIO a realizar três orçamentos e providenciar a realização dos reparos que importem a estrutura ou segurança do imóvel e cobrá-los do LOCADOR pelo menor preço orçado."}, {"id": "p052", "t": "Cláusula 24º - Fica ainda facultado ao LOCADOR quando lhe convier, exigir a remoção de benfeitorias introduzidas no imóvel sem sua autorização, correndo todas as despesas por conta do LOCATÁRIO."}, {"id": "p053", "t": "Cláusula 25º - Se na VISTORIA FINAL for constatado qualquer anormalidade no imóvel, o LOCATÁRIO será notificado no prazo de 05 (cinco) dias corridos, para reparar o defeito ou substituir as peças ou aparelhos defeituosos por sua conta e risco. Não atendida esta notificação, ficará facultado ao LOCADOR providenciar os serviços, cobrando do LOCATÁRIO, os valores gastos com material e mão de obra, além dos dias de aluguel necessários para tais reparos."}, {"id": "p054", "t": "Parágrafo único: As partes concordam que a vistoria final do imóvel será realizada sem qualquer custo para o LOCATÁRIO. Contudo, caso seja necessária a realização de uma revistoria, será cobrada uma taxa de R$ 120,00 (cento e vinte) reais para cobrir custos envolvidos."}, {"id": "p055", "t": "Cláusula 26º - O LOCATÁRIO desde já, faculta o LOCADOR, ou seu representante devidamente constituído, examinar ou vistoriar o imóvel locado, quando entender conveniente, com aviso de 48 (quarenta e oito) horas de antecedência."}, {"id": "p056", "t": "Cláusula 27º - Ocorrerá a rescisão do presente contrato de pleno direito, no caso de desapropriação, incêndio ou acidente que sujeite o imóvel locado a obras que importem na sua reconstrução ainda que parcial, que impeçam o seu uso por mais de 45 (quarenta e cinco) dias, ou, ainda, no caso de se verificar ou ocorrer a insolvência, recuperação judicial ou falência do LOCATÁRIO, ou se forem verificados atos desabonadores, de ordem civil ou criminal de sua parte, sem prejuízo das demais cláusulas contratuais e da responsabilidade da multa contratual estipulada na CLÁUSULA 28º, que alcançará também os Fiadores (se houver)."}, {"id": "p057", "t": "Cláusula 28º - No caso de desapropriação do imóvel locado, ficará o LOCADOR desobrigado por todas as cláusulas deste contrato, ressalvando-se ao LOCATÁRIO tão somente o direito de haver do poder público desapropriante a indenização a que porventura tenha direito."}, {"id": "p058", "t": "Cláusula 29º - O LOCATÁRIO é obrigado a respeitar os direitos de vizinhança, a lei do silêncio, regras de condomínio, evitando a prática de quaisquer atos que venham a perturbar a tranquilidade e as condições de saúde pública."}, {"id": "p059", "t": "Parágrafo primeiro: Ocorrerá também a rescisão do presente contrato se o LOCATÁRIO infringir obrigação legal ou cometer infração a qualquer uma das cláusulas do presente instrumento."}, {"id": "p060", "t": "Parágrafo segundo: Fica estipulada a multa contratual compensatória proporcional de 03 (três) vezes o valor do aluguel vigente da época da eventual infração, em benefício ao LOCADOR, sem prejuízo da exigibilidade das obrigações assumidas por este instrumento, podendo o LOCADOR, se assim lhe convier, considerar ao mesmo tempo rescindido o presente contrato de locação, independentemente de qualquer formalidade."}, {"id": "p062", "t": "Cláusula 31º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p064", "t": "Parágrafo único: Na ausência do aviso acima citado, o LOCADOR poderá exigir a quantia correspondente a 01 (um) mês de aluguel e encargos vigentes da data da rescisão, conforme autoriza o artigo 6º, da Lei no 8.245/91."}, {"id": "p065", "t": "Cláusula 33º - Tudo quanto for devido em razão deste contrato, notadamente os aluguéis mensais e seus acessórios, será cobrado por ação judicial apropriada no FORO TERRITORIAL DO IMÓVEL, com expressa renúncia de qualquer outro, por mais privilegiado que seja, o qual desde já fica eleito pelos contratantes como seu domicílio, para que exercitem e cumpram todos os direitos e obrigações decorrentes do presente instrumento."}, {"id": "p066", "t": "Parágrafo único: Em qualquer procedimento judicial que o LOCATÁRIO der causa, correrão por sua conta além do principal, todas as custas e despesas oriundas desta medida e ainda, honorários advocatícios, mesmo em caso de purgação de mora, quando houver a propositura da ação ou logo após a distribuição da petição."}, {"id": "p067", "t": "Cláusula 34º - Não é permitida a transferência deste contrato, no todo ou em parte, a sublocação ou empréstimo do imóvel locado, sem prévio consentimento, por escrito do LOCADOR."}, {"id": "p068", "t": "Parágrafo único: Em caso de falecimento, separação de fato ou judicial, divórcio ou dissolução da união estável do LOCATÁRIO, esta locação prosseguirá automaticamente com seu cônjuge ou companheiro, este que permanecer no imóvel, nos termos da Lei."}, {"id": "p069", "t": "Cláusula 35º - Caso o imóvel seja colocado à venda, o LOCATÁRIO terá preferência na compra. Não havendo interesse no prazo de 30 (trinta) dias, o LOCATÁRIO deverá permitir e facilitar as visitas dos pretendentes ao mesmo, em conformidade com o artigo 27, da Lei no 8.245/91."}, {"id": "p072", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p073", "t": "Cláusula 38º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da parte perecível do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p076", "t": "Cláusula 39º - A falta do pagamento do seguro por parte do LOCATÁRIO, constituirá infração passível de rescisão do presente instrumento, independente da incidência da multa infracional prevista em contrato."}, {"id": "p077", "t": "Cláusula 40º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro mencionado na CLÁUSULA 38º."}, {"id": "p079", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p082", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p083", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p084", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p085", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p086", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p087", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p088", "t": "[[ASSINATURAS]]"}]$inter$::jsonb, 'Rascunho só intermediação, revisão jurídica pendente');
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, $inter$seguro_almada_intermediacao$inter$, 1, $inter$Garantia Almada — só intermediação$inter$, $inter$residencial$inter$, $inter$seguro_fianca$inter$, $inter$almada$inter$, $inter$SEGURO FIANÇA ALMADA$inter$, $inter$[{"id": "p001", "t": "PRÊAMBULO"}, {"id": "p002", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p003", "t": "[[LOCADOR]]"}, {"id": "p004", "t": "[[LOCATARIO]]"}, {"id": "p007", "t": "APÓLICE: [APOLICE_REFERENCIA]"}, {"id": "p008", "t": "[[OBJETO]]"}, {"id": "p009", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p010", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p011", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso de MORADIA dos LOCATÁRIO (S).", "dest": "residencial"}, {"id": "p012", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso COMERCIAL dos LOCATÁRIO (S).", "dest": "comercial", "adaptado": true}, {"id": "p013", "t": "[[PRAZO]]"}, {"id": "p014", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), conforme acordado entre as partes e o(a) LOCATÁRIO(A) se compromete a pagar pontualmente até o dia [DIA_VENCIMENTO] de cada mês subsequente."}, {"id": "p015", "t": "Cláusula 2º - O primeiro aluguel será pago 30 dias após a data de entrega das chaves e os aluguéis subsequentes, serão pagos na data de vencimento fixada neste documento."}, {"id": "p016", "t": "[[ADICIONAIS]]"}, {"id": "p017", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p018", "t": "O valor do aluguel pode ser acrescido de acessórios locatícios e encargos, se aplicável, conforme estipulado neste contrato. O cômputo desses encargos será a partir da posse da chave e serão cobrados juntamente com o aluguel na data estabelecida."}, {"id": "p019", "t": "Cláusula 3º - O aluguel mensal deve ser pago juntamente com os demais encargos, em moeda corrente nacional, em seu vencimento, ficando em caso contrário acrescidos de multa de 10% (dez por cento) do seu valor, mais juros de 1% (um por cento) ao mês, mais a correção monetária prevista em lei, a título de penalidade contratual, sem prejuízo da exigibilidade das demais correções estipuladas."}, {"id": "p022", "t": "Cláusula 6º - Além das penalidades previstas na CLÁUSULA 3º, a falta de pagamento do aluguel na data estipulada poderá acarretar a rescisão do presente contrato, após 15 (quinze) dias da data do vencimento, ficando o LOCATÁRIO(S) responsável pela multa prevista na CLÁUSULA 28º - Parágrafo segundo do presente contrato, pelas despesas processuais e honorários advocatícios."}, {"id": "p023", "t": "Cláusula 7º - O LOCATÁRIO(S) não terá direito a reter o pagamento do aluguel ou de qualquer outra quantia devida nos termos do presente contrato, sob a alegação de não terem sido atendidas exigências porventura solicitadas."}, {"id": "p024", "t": "Cláusula 8º – O LOCATÁRIO(S) fica ciente nesta data que, antes da propositura da ação de despejo por falta de pagamento do aluguel e encargos na data estipulada neste contrato, poderá haver o protesto, junto ao cartório competente."}, {"id": "p025", "t": "Cláusula 9º - Eventual inadimplência do aluguel e encargos por parte dos LOCATÁRIO (S), ensejará Ação Judicial, independente do prazo da mora, não se responsabilizando o LOCADOR(A) pela inclusão dos nomes dos devedores ou de seus Fiadores junto às entidades mantenedoras de bancos de proteção ao crédito, SERASA, SCPC etc."}, {"id": "p026", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p027", "t": "O valor do aluguel ora contratado sofrerá reajuste anualmente, em conformidade com a legislação específica. Entretanto, havendo alteração legal para nova periodicidade, esta será aplicada automaticamente, independentemente de confirmação das partes."}, {"id": "p028", "t": "INDEXADORES:"}, {"id": "p029", "t": "As partes de comum acordo estabelecem o índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), para a correção do aluguel, que será aplicado de acordo com a periodicidade acima. Havendo a extinção do mesmo, por determinação legal, as partes elegerão seu substituto imediatamente após a eventual extinção."}, {"id": "p032", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p033", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p034", "t": "Cláusula 12º – O LOCATÁRIO obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das contas de ÁGUA, ENERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade das referidas contas, por parte do LOCATÁRIO, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p035", "t": "Cláusula 13º – O descumprimento da obrigação prevista na CLÁUSULA 12º, autoriza o LOCADOR a reter as chaves até a devida apresentação dos respectivos comprovantes, sem que isso gere qualquer direito de indenização ou alegação de atraso na imissão da posse por parte do LOCATÁRIO."}, {"id": "p036", "t": "Cláusula 14º - O LOCATÁRIO recebendo na data da assinatura deste contrato, o respectivo laudo de vistoria inicial, cujo documento aponta o estado de conservação do imóvel, declara concordar que o imóvel tem como finalidade, o uso de HABITAÇÃO, considerando inclusive suas instalações ELÉTRICAS, HIDRÁULICAS e SANITÁRIAS. Obriga-se o LOCATÁRIO a manter o imóvel assim como consta em LAUDO DE VISTORIA INICIAL, de forma a tudo restituir na mais perfeita ordem e no mesmo estado de conservação, higiene e funcionamento, quando findo ou rescindido o presente contrato, de modo que possa ser imediatamente ocupado pelo LOCADOR ou por quem este indicar, sem que isso dependa de qualquer conserto, reparação, etc. O LOCADOR será responsável pelos problemas estruturais, caso seja necessario.", "dest": "residencial"}, {"id": "p037", "t": "Cláusula 14º - O LOCATÁRIO recebendo na data da assinatura deste contrato, o respectivo laudo de vistoria inicial, cujo documento aponta o estado de conservação do imóvel, declara concordar que o imóvel tem como finalidade, o uso COMERCIAL, considerando inclusive suas instalações ELÉTRICAS, HIDRÁULICAS e SANITÁRIAS. Obriga-se o LOCATÁRIO a manter o imóvel assim como consta em LAUDO DE VISTORIA INICIAL, de forma a tudo restituir na mais perfeita ordem e no mesmo estado de conservação, higiene e funcionamento, quando findo ou rescindido o presente contrato, de modo que possa ser imediatamente ocupado pelo LOCADOR ou por quem este indicar, sem que isso dependa de qualquer conserto, reparação, etc. O LOCADOR será responsável pelos problemas estruturais, caso seja necessario.", "dest": "comercial", "adaptado": true}, {"id": "p038", "t": "Cláusula 15º - Em caso de discordância do laudo de vistoria inicial, o LOCATÁRIO terá o prazo de 10 (dez) dias corridos para realizar sua contestação, mediante formalização por email ou notificação por correios. O silêncio será considerado concordância ao laudo inicial apresentado."}, {"id": "p039", "t": "Cláusula 16º - Fica terminantemente proibida a colocação de pregos e parafusos nas paredes ou executar furos nos azulejos. Caso o LOCATÁRIO necessite fixar armários de cozinha ou outros, deverá solicitar autorização por escrito ao LOCADOR, ocasião em que, uma vez autorizado, receberá uma cópia da planta hidráulica e elétrica do imóvel."}, {"id": "p040", "t": "Cláusula 17º - A repintura no imóvel ora locado por parte do LOCATÁRIO, deverá ser compatível com a tinta anterior, ou seja, nas mesmas cores e qualidade que foi entregue."}, {"id": "p041", "t": "Cláusula 18º - Os pisos, azulejos, armários modulados, ou qualquer item de acabamento do imóvel ora locado por parte do LOCATÁRIO, deverá ser entregue nas mesmas condições recebidas, ou seja, caso danifique algum desses itens, o mesmo deverá ser substituído pelo mesmo modelo, tamanho, marca e nas mesmas cores e qualidade que foi entregue."}, {"id": "p043", "t": "Cláusula 20º - Fica o LOCATÁRIO, responsável pela verificação da voltagem da corrente elétrica existente no imóvel, em todos os seus pontos, assumindo para si, eventuais danos em aparelhos e/ou equipamentos que sejam ligados sem a devida checagem."}, {"id": "p044", "t": "Cláusula 21º - O LOCATÁRIO não poderá fazer modificações ou transformações no imóvel locado, nem introduzir quaisquer benfeitorias, sem que haja prévio aviso e consentimento por escrito do LOCADOR. Realizado benfeitorias, desde que tenham sido com o consentimento expresso da LOCADOR, essas ficarão incorporadas ao imóvel sem qualquer direito ao LOCATÁRIO, de retenção ou indenização, ao término da locação."}, {"id": "p045", "t": "Cláusula 22º - São de responsabilidade do LOCATÁRIO as obras de manutenção do imóvel, cabendo exclusivamente ao LOCADOR aquelas que importem na estrutura e segurança dele, nos termos da legislação vigente. I): Sendo necessária a realização de qualquer obra ou manutenção por parte do LOCADOR, o LOCATÁRIO deverá notifica-lo para que no prazo de até 05 (cinco) dias úteis do recebimento da notificação, dar início aos reparos necessários. Não sendo realizados, fica desde já autorizado o LOCATÁRIO a realizar três orçamentos e providenciar a realização dos reparos que importem a estrutura ou segurança do imóvel e cobrá-los do LOCADOR pelo menor preço orçado."}, {"id": "p046", "t": "Cláusula 23º - Fica ainda facultado ao LOCADOR quando lhe convier, exigir a remoção de benfeitorias introduzidas no imóvel sem sua autorização, correndo todas as despesas por conta do LOCATÁRIO."}, {"id": "p047", "t": "Cláusula 24º - Se na VISTORIA FINAL for constatado qualquer anormalidade no imóvel, o LOCATÁRIO será notificado no prazo de 05 (cinco) dias corridos, para reparar o defeito ou substituir as peças ou aparelhos defeituosos por sua conta e risco. Não atendida esta notificação, ficará facultado ao LOCADOR providenciar os serviços, cobrando do LOCATÁRIO, os valores gastos com material e mão de obra, além dos dias de aluguel necessários para tais reparos."}, {"id": "p048", "t": "Parágrafo único: As partes concordam que a vistoria final do imóvel será realizada sem qualquer custo para o LOCATÁRIO. Contudo, caso seja necessária a realização de uma revistoria, será cobrada uma taxa de R$ 120,00 (cento e vinte) reais para cobrir custos envolvidos."}, {"id": "p049", "t": "Cláusula 25º - O LOCATÁRIO desde já, faculta o LOCADOR, ou seu representante devidamente constituído, examinar ou vistoriar o imóvel locado, quando entender conveniente, com aviso de 48 (quarenta e oito) horas de antecedência."}, {"id": "p050", "t": "Cláusula 26º - Ocorrerá a rescisão do presente contrato de pleno direito, no caso de desapropriação, incêndio ou acidente que sujeite o imóvel locado a obras que importem na sua reconstrução ainda que parcial, que impeçam o seu uso por mais de 45 (quarenta e cinco) dias, ou, ainda, no caso de se verificar ou ocorrer a insolvência, recuperação judicial ou falência do LOCATÁRIO, ou se forem verificados atos desabonadores, de ordem civil ou criminal de sua parte, sem prejuízo das demais cláusulas contratuais e da responsabilidade da multa contratual estipulada na CLÁUSULA 28º, que alcançará também os Fiadores (se houver)."}, {"id": "p051", "t": "Cláusula 27º - No caso de desapropriação do imóvel locado, ficará o LOCADOR desobrigado por todas as cláusulas deste contrato, ressalvando-se ao LOCATÁRIO tão somente o direito de haver do poder público desapropriante a indenização a que porventura tenha direito."}, {"id": "p052", "t": "Cláusula 28º - O LOCATÁRIO é obrigado a respeitar os direitos de vizinhança, a lei do silêncio, regras de condomínio, evitando a prática de quaisquer atos que venham a perturbar a tranquilidade e as condições de saúde pública."}, {"id": "p053", "t": "Parágrafo primeiro: Ocorrerá também a rescisão do presente contrato se o LOCATÁRIO infringir obrigação legal ou cometer infração a qualquer uma das cláusulas do presente instrumento."}, {"id": "p054", "t": "Parágrafo segundo: Fica estipulada a multa contratual compensatória proporcional de 03 (três) vezes o valor do aluguel vigente da época da eventual infração, em benefício ao LOCADOR, sem prejuízo da exigibilidade das obrigações assumidas por este instrumento, podendo o LOCADOR, se assim lhe convier, considerar ao mesmo tempo rescindido o presente contrato de locação, independentemente de qualquer formalidade."}, {"id": "p056", "t": "Cláusula 30º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p058", "t": "Parágrafo único: Na ausência do aviso acima citado, o LOCADOR poderá exigir a quantia correspondente a 01 (um) mês de aluguel e encargos vigentes da data da rescisão, conforme autoriza o artigo 6º, da Lei no 8.245/91."}, {"id": "p059", "t": "Cláusula 32º - Tudo quanto for devido em razão deste contrato, notadamente os aluguéis mensais e seus acessórios, será cobrado por ação judicial apropriada no FORO TERRITORIAL DO IMÓVEL, com expressa renúncia de qualquer outro, por mais privilegiado que seja, o qual desde já fica eleito pelos contratantes como seu domicílio, para que exercitem e cumpram todos os direitos e obrigações decorrentes do presente instrumento."}, {"id": "p060", "t": "Parágrafo único: Em qualquer procedimento judicial que o LOCATÁRIO der causa, correrão por sua conta além do principal, todas as custas e despesas oriundas desta medida e ainda, honorários advocatícios, mesmo em caso de purgação de mora, quando houver a propositura da ação ou logo após a distribuição da petição."}, {"id": "p061", "t": "Cláusula 33º - Não é permitida a transferência deste contrato, no todo ou em parte, a sublocação ou empréstimo do imóvel locado, sem prévio consentimento, por escrito do LOCADOR."}, {"id": "p062", "t": "Parágrafo único: Em caso de falecimento, separação de fato ou judicial, divórcio ou dissolução da união estável do LOCATÁRIO, esta locação prosseguirá automaticamente com seu cônjuge ou companheiro, este que permanecer no imóvel, nos termos da Lei."}, {"id": "p063", "t": "Cláusula 34º - Caso o imóvel seja colocado à venda, o LOCATÁRIO terá preferência na compra. Não havendo interesse no prazo de 30 (trinta) dias, o LOCATÁRIO deverá permitir e facilitar as visitas dos pretendentes ao mesmo, em conformidade com o artigo 27, da Lei no 8.245/91."}, {"id": "p066", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p067", "t": "Cláusula 37º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da parte perecível do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p070", "t": "Cláusula 38º - A falta do pagamento do seguro por parte do LOCATÁRIO, constituirá infração passível de rescisão do presente instrumento, independente da incidência da multa infracional prevista em contrato."}, {"id": "p071", "t": "Cláusula 39º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro mencionado na CLÁUSULA 38º."}, {"id": "p073", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p076", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p077", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p078", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p079", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p080", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p081", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p082", "t": "[[ASSINATURAS]]"}]$inter$::jsonb, 'Rascunho só intermediação, revisão jurídica pendente');
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, $inter$loft_intermediacao$inter$, 1, $inter$Loft (CredPago) — só intermediação$inter$, $inter$residencial$inter$, $inter$loft$inter$, NULL, $inter$CREDPAGO$inter$, $inter$[{"id": "p001", "t": "QUADRO RESUMO: Locador(es); Locatário(a); Imóvel; Destinação da Locação; Prazo da Locação; Valor e Vencimento do Aluguel; Primeiro Aluguel; Reajuste e Indexador; Encargos Locatícios; Contas de Consumo; Transferência de Titularidade; Garantia Locatícia; Inadimplência; Vistoria Inicial; Contestação da Vistoria; Conservação e Manutenção do Imóvel; Benfeitorias e Modificações; Vistoria Final e Revistoria; Rescisão e Multa Contratual; Desocupação e Aviso Prévio; Seguro Incêndio; Sublocação/Cessão; Preferência na Compra do Imóvel; LGPD; Disposições Gerais; Foro."}, {"id": "p002", "t": "PRÊAMBULO"}, {"id": "p003", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p004", "t": "[[LOCADOR]]"}, {"id": "p005", "t": "[[LOCATARIO]]"}, {"id": "p008", "t": "O LOCADOR e o Inquilino declaram estar cientes e de acordo com todas as condições e limitações relativas à fiança prestada pela LOFT, notadamente, no tocante a: (i) o valor máximo afiançado, (ii) as limitações da responsabilidade da LOFT; (iii) o prazo de vigência da fiança contratada; (iv) as condições para sua renovação; (v) a possibilidade da LOFT substituir a fiança prestada por outra Modalidade de Garantia, especialmente, por seguro garantia financeiro; (vi) as hipóteses de término da FIANÇA ALUGUEL, que ocorrerá pelo primeiro dos seguintes eventos: (a) a entrega das chaves do Imóvel ao Locador; (b) a certidão de despejo emitida por Oficial de Justiça em ação de despejo; ou (c) a desocupação e disponibilização do Imóvel ao Locador; (vii) a inaplicabilidade, em relação à LOFT, de eventuais cláusulas deste instrumento que contrariem os T&C; e (viii) a rescisão imediata da FIANÇA ALUGUEL, com a consequente liberação da LOFT do pagamento de qualquer nova indenização, em caso de inadimplemento da contraprestação devida à LOFT pela prestação da fiança (“Taxa LOFT”).", "trava": true}, {"id": "p009", "t": "O Inquilino e o LOCADOR reconhecem que, o Contrato de Locação será considerado automaticamente rescindido e, por consequência, também será rescindida a garantia LOFT FIANÇA ALUGUEL em qualquer das hipóteses de término, previstas anteriormente, ficando a LOFT imediatamente liberada do pagamento de qualquer indenização.", "trava": true}, {"id": "p012", "t": "E o Inquilino concorda expressamente que, em caso exoneração da LOFT como fiadora por qualquer motivo detalhado no T&C, especialmente decorrente do inadimplemento do Inquilino, caberá a ele, promover, no prazo máximo de 30 (trinta) dias, a substituição da garantia locatícia prestada, o que só ocorrerá mediante expresso aceite da nova modalidade pelo LOCADOR, sob pena de infração contratual e ajuizamento da competente ação de despejo.", "trava": true}, {"id": "p013", "t": "O e-mail indicado pelo Inquilino para a Loft quando da contratação da FIANÇA ALUGUEL será considerado apto para recebimento de qualquer comunicação (inclusive judiciais) acerca do Contrato de Locação e decorrentes do T&C, independentemente de confirmação de recebimento. Desta forma, o Inquilino tem ciência que deverá manter seus dados cadastrais atualizados junto a LOFT.", "trava": true}, {"id": "p014", "t": "Para fins de cumprimento das obrigações previstas neste Contrato de Locação e nos T&C a ele vinculados, o LOCADOR, por meio deste instrumento, outorga poderes específicos à LOFT, na qualidade de fiadora do contrato de locação, de forma expressa, irrevogável e irretratável, mandato específico para representá-lo nas seguintes situações:", "trava": true}, {"id": "p016", "t": "(b) Notificar o LOCATÁRIO, em nome do LOCADOR, em especial para que apresente nova modalidade de garantia locatícia no prazo de até 30 (trinta) dias, conforme previsto no artigo 40, §2º da Lei nº 8.245/1991 (Lei do Inquilinato), sob pena de rescisão contratual e adoção das medidas legais cabíveis;", "trava": true}, {"id": "p017", "t": "(c) Na hipótese de adesão à solução de Gestão de Despejos prestado pela LOFT, contratar advogado(s) e outorgar-lhes poderes, para promover, em nome do LOCADOR, o ajuizamento, condução e acompanhamento de ação de despejo, bem como outras ações judiciais ou procedimentos arbitrais relacionados à presente locação, incluindo, mas não se limitando a ações possessórias, medidas cautelares e ações de cobrança, perante qualquer juízo, instância, tribunal ou câmara arbitral (procuração ad judicia);", "trava": true}, {"id": "p018", "t": "(d) Ainda na hipótese de adesão à solução de Gestão de Despejos, os advogados contratados poderão receber poderes especiais para, em nome do LOCADOR, transigir, desistir, receber e dar quitação, firmar compromissos, renunciar a direitos, desistir de recursos e/ou reconhecer a procedência de pedidos, desde que tais atos estejam relacionados à defesa dos interesses do LOCADOR no âmbito da locação ora contratada.", "trava": true}, {"id": "p019", "t": "Parágrafo Primeiro: Os poderes permanecerão válidos enquanto vigente o presente contrato ou até que sejam expressamente revogados por instrumento escrito e registrado, sem prejuízo da validade dos atos já praticados.", "trava": true}, {"id": "p021", "t": "ANEXO I – Termos e Condições Gerais da FIANÇA ALUGUEL (LOFT): [LOFT_REFERENCIA]"}, {"id": "p022", "t": "[[OBJETO]]"}, {"id": "p023", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p024", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p025", "t": "O imóvel identificado neste instrumento destina-se exclusivamente à MORADIA do LOCATÁRIO e dos moradores expressamente identificados neste contrato, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "residencial"}, {"id": "p026", "t": "O imóvel identificado neste instrumento destina-se exclusivamente ao uso COMERCIAL do LOCATÁRIO, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "comercial", "adaptado": true}, {"id": "p027", "t": "[[PRAZO]]"}, {"id": "p028", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), devendo ser pago pelo LOCATÁRIO até o dia [DIA_VENCIMENTO] de cada mês, conforme as condições estabelecidas neste instrumento."}, {"id": "p029", "t": "Cláusula 2º - O primeiro aluguel vencerá 30 (trinta) dias após a efetiva entrega das chaves ao LOCATÁRIO. Os aluguéis subsequentes vencerão todo dia [DIA_VENCIMENTO] de cada mês, observando-se, quando necessário, o cálculo proporcional dos períodos de ocupação, a fim de evitar cobrança em duplicidade."}, {"id": "p030", "t": "[[ADICIONAIS]]"}, {"id": "p031", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p032", "t": "Além do aluguel mensal, serão de responsabilidade do LOCATÁRIO os encargos locatícios expressamente atribuídos a ele neste contrato, os quais serão devidos a partir da efetiva entrega das chaves, observadas as disposições legais e contratuais aplicáveis."}, {"id": "p033", "t": "Cláusula 3º - O atraso no pagamento do aluguel ou de quaisquer encargos locatícios acarretará a incidência de multa moratória de 10% (dez por cento) sobre o valor devido, acrescida de juros de mora de 1% (um por cento) ao mês, calculados proporcionalmente aos dias de atraso, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p036", "t": "Cláusula 6º - O inadimplemento do aluguel ou de quaisquer encargos locatícios na data do vencimento constituirá o LOCATÁRIO em mora, independentemente de notificação, facultando ao LOCADOR adotar as medidas judiciais e extrajudiciais cabíveis, inclusive ação de despejo e cobrança, nos termos da Lei nº 8.245/91, sem prejuízo dos encargos moratórios previstos neste contrato."}, {"id": "p038", "t": "Cláusula 8º – O LOCATÁRIO declara estar ciente de que o inadimplemento das obrigações financeiras decorrentes deste contrato poderá ensejar o protesto dos respectivos débitos, observadas as exigências legais aplicáveis."}, {"id": "p039", "t": "Cláusula 9º - O inadimplemento das obrigações locatícias poderá ensejar a adoção das medidas judiciais cabíveis, bem como a comunicação dos débitos aos órgãos de proteção ao crédito, desde que observados os requisitos legais, inclusive quanto à legitimidade, exatidão e atualização das informações fornecidas."}, {"id": "p040", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p041", "t": "O valor do aluguel será reajustado anualmente, respeitado o intervalo mínimo permitido pela legislação vigente, mediante aplicação do índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), ou de outro índice oficial que venha a substituí-lo em caso de sua extinção, observadas as disposições legais aplicáveis."}, {"id": "p044", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p045", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p046", "t": "Cláusula 12º – O locatário obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das de ÁGUA, ELERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p047", "t": "DO DESCUMPRIMENTO E DAS PROVIDÊNCIAS ADMINISTRATIVAS:"}, {"id": "p051", "t": "Cláusula 14º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso para HABITAÇÃO.", "dest": "residencial"}, {"id": "p052", "t": "Cláusula 14º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso COMERCIAL.", "dest": "comercial", "adaptado": true}, {"id": "p054", "t": "Cláusula 16º - Fica permitido ao LOCATÁRIO realizar pequenos furos nas paredes do imóvel para a fixação de quadros, espelhos, suportes e objetos similares, desde que não comprometam a estrutura, as instalações hidráulicas ou elétricas. Fica expressamente vedada a realização de furos em azulejos, revestimentos cerâmicos e áreas impermeabilizadas, salvo mediante autorização prévia e por escrito do LOCADOR. Ao término da locação, o LOCATÁRIO deverá providenciar a adequada reparação dos furos realizados nas paredes, recompondo a pintura e o acabamento quando necessário, restituindo o imóvel nas condições em que o recebeu, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p055", "t": "Cláusula 17º - O LOCATÁRIO deverá devolver o imóvel com a pintura nas mesmas condições em que o recebeu, conforme descrito no laudo de vistoria inicial, responsabilizando-se pela reparação de manchas, riscos, alterações de cores, descascamentos ou danos decorrentes de uso inadequado ou de sua responsabilidade, ressalvado o desgaste natural decorrente do uso regular do imóvel."}, {"id": "p056", "t": "Cláusula 18º - O LOCATÁRIO deverá zelar pela conservação dos pisos, azulejos, armários, acessórios e demais itens que integram o imóvel, responsabilizando-se pelos danos que causar por ação, omissão ou uso inadequado, devendo providenciar o reparo ou a substituição dos itens danificados por outros de padrão, qualidade e características equivalentes aos originalmente existentes, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p058", "t": "Cláusula 20º - O LOCATÁRIO deverá verificar a tensão elétrica disponível nos pontos de energia do imóvel antes de conectar seus equipamentos e aparelhos eletrônicos, responsabilizando-se pelos danos decorrentes da utilização inadequada ou incompatível com a tensão disponível, desde que as instalações tenham sido entregues em condições regulares de funcionamento e que as informações disponíveis tenham sido corretamente fornecidas."}, {"id": "p059", "t": "Cláusula 21º - O LOCATÁRIO não poderá realizar modificações, alterações ou benfeitorias no imóvel sem prévia autorização, por escrito, do LOCADOR. Salvo ajuste expresso em contrário, as benfeitorias realizadas, ainda que autorizadas, incorporar-se-ão ao imóvel, sem direito de indenização ou retenção pelo LOCATÁRIO, nos termos do artigo 35 da Lei nº 8.245/91 e da Súmula 335 do STJ, ressalvadas as obrigações legais do LOCADOR relativas à conservação, segurança e habitabilidade do imóvel."}, {"id": "p060", "t": "Cláusula 22º - Compete ao LOCATÁRIO realizar os reparos e serviços de manutenção decorrentes do uso regular do imóvel, bem como reparar os danos causados por si, seus moradores, visitantes ou terceiros sob sua responsabilidade. Compete ao LOCADOR realizar os reparos relativos a vícios anteriores à locação, problemas estruturais e defeitos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, desde que não decorrentes de ação ou omissão do LOCATÁRIO."}, {"id": "p062", "t": "Cláusula 23º - O LOCADOR poderá exigir que o LOCATÁRIO remova modificações ou benfeitorias realizadas sem autorização prévia e por escrito, quando necessário à recomposição do imóvel às condições originais, correndo as despesas correspondentes por conta do LOCATÁRIO, desde que decorrentes de sua responsabilidade."}, {"id": "p063", "t": "Cláusula 24º - Ao término da locação, será realizada vistoria final para verificar as condições de conservação do imóvel, mediante comparação com o laudo de vistoria inicial, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p064", "t": "Parágrafo 1º: Caso sejam constatados danos ou irregularidades de responsabilidade do LOCATÁRIO, este será comunicado para que possa providenciar os respectivos reparos no prazo de 05 (cinco) dias corridos, ou outro prazo acordado entre as partes, sem prejuízo da cobrança de eventuais valores necessários à recomposição do imóvel."}, {"id": "p065", "t": "Parágrafo 2º: Caso o LOCATÁRIO não realize os reparos de sua responsabilidade, o LOCADOR poderá providenciá-los e exigir o ressarcimento dos respectivos custos, mediante apresentação dos comprovantes pertinentes, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p066", "t": "Parágrafo 3º: A vistoria final será realizada sem custo para o LOCATÁRIO. Caso seja necessária nova vistoria para verificação dos reparos executados, poderá ser cobrada taxa de revistoria no valor de R$ 150,00 (cento e cinquenta reais), desde que previamente informada e relacionada à necessidade de nova verificação de pendências de responsabilidade do LOCATÁRIO."}, {"id": "p067", "t": "Parágrafo 4º: A existência de danos ou pendências apontadas na vistoria não impedirá o recebimento das chaves nem a formalização da devolução do imóvel, permanecendo assegurado ao LOCADOR o direito de exigir o ressarcimento dos prejuízos comprovadamente atribuíveis ao LOCATÁRIO."}, {"id": "p068", "t": "Cláusula 25º - O LOCATÁRIO permitirá que o LOCADOR ou seu representante devidamente autorizado examine ou vistori? o imóvel, mediante prévio agendamento e comunicação com antecedência mínima de 48 (quarenta e oito) horas, em dia e horário previamente acordados entre as partes, respeitado o direito à privacidade e ao uso pacífico do imóvel."}, {"id": "p069", "t": "Cláusula 26º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade residencial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "residencial"}, {"id": "p070", "t": "Cláusula 26º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade comercial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "comercial", "adaptado": true}, {"id": "p071", "t": "Cláusula 27º - Em caso de desapropriação do imóvel, a locação será extinta, ficando o LOCADOR desobrigado das obrigações futuras decorrentes deste contrato, ressalvados os direitos do LOCATÁRIO de pleitear eventual indenização diretamente perante o poder público desapropriante, quando legalmente cabível."}, {"id": "p072", "t": "Cláusula 28º - O LOCATÁRIO obriga-se a respeitar as normas de convivência, os direitos de vizinhança, as regras condominiais e a legislação vigente, abstendo-se de praticar atos que comprometam a segurança, a tranquilidade, a higiene ou o sossego dos demais moradores."}, {"id": "p073", "t": "Parágrafo primeiro: O descumprimento das obrigações legais ou contratuais poderá ensejar a aplicação das medidas cabíveis, inclusive rescisão da locação, conforme a natureza e a gravidade da infração, observadas as disposições da Lei nº 8.245/91."}, {"id": "p074", "t": "Parágrafo segundo: Fica estipulada multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente à época da infração, aplicável em caso de descumprimento contratual que justifique sua incidência, observados os critérios de proporcionalidade, a natureza da obrigação descumprida e a legislação vigente."}, {"id": "p075", "t": "Parágrafo terceiro: Na hipótese de devolução antecipada do imóvel por iniciativa do LOCATÁRIO durante o prazo determinado deste contrato, será devida multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente, calculada proporcionalmente ao período restante do contrato, conforme o artigo 4º da Lei nº 8.245/91."}, {"id": "p077", "t": "Cláusula 30º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p079", "t": "Parágrafo único: Na ausência do aviso prévio previsto nesta cláusula, o LOCADOR poderá exigir quantia correspondente a 01 (um) mês de aluguel e encargos vigentes na data da rescisão, conforme disposto no artigo 6º, parágrafo único, da Lei nº 8.245/91."}, {"id": "p080", "t": "Cláusula 32º - Fica eleito o foro da comarca onde se localiza o imóvel objeto desta locação para dirimir quaisquer controvérsias decorrentes deste contrato, ressalvadas as hipóteses legais de competência absoluta."}, {"id": "p081", "t": "Parágrafo único: Em caso de demanda judicial decorrente do descumprimento das obrigações contratuais, as partes responderão pelas custas e despesas processuais, conforme a legislação vigente e eventual determinação judicial."}, {"id": "p082", "t": "Cláusula 33º - É vedado ao LOCATÁRIO ceder, transferir ou sublocar, total ou parcialmente, o imóvel objeto deste contrato, bem como emprestá-lo a terceiros, sem prévia autorização expressa e por escrito do LOCADOR, nos termos do artigo 13 da Lei nº 8.245/91."}, {"id": "p083", "t": "Parágrafo único: Em caso de separação de fato, separação judicial, divórcio ou dissolução da união estável do LOCATÁRIO, a locação prosseguirá automaticamente com aquele que permanecer no imóvel, observadas as disposições do artigo 12 da Lei nº 8.245/91, inclusive quanto à comunicação ao LOCADOR e ao FIADOR."}, {"id": "p084", "t": "Cláusula 34º - Caso o LOCADOR pretenda vender o imóvel durante a vigência da locação, deverá assegurar ao LOCATÁRIO o direito de preferência para aquisição, em igualdade de condições com terceiros, mediante comunicação formal contendo todas as condições do negócio, inclusive preço, forma de pagamento e demais informações pertinentes, nos termos dos artigos 27 e seguintes da Lei nº 8.245/91."}, {"id": "p085", "t": "Parágrafo único: O LOCATÁRIO terá o prazo legal de 30 (trinta) dias, contado do recebimento da comunicação, para manifestar sua aceitação integral e inequívoca da proposta. Caso não exerça o direito de preferência, deverá permitir visitas de interessados, mediante prévio agendamento e em horários previamente acordados."}, {"id": "p088", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p089", "t": "Cláusula 37º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da estrutura e partes integrantes do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p092", "t": "Cláusula 38º - O descumprimento da obrigação de contratação ou renovação do seguro contra incêndio, após notificação para regularização, poderá caracterizar infração contratual, sujeitando o LOCATÁRIO às medidas legais e contratuais cabíveis."}, {"id": "p093", "t": "Cláusula 39º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro incêndio individual."}, {"id": "p095", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p097", "t": "Cláusula 42º - O tratamento de dados pessoais para finalidades adicionais, não abrangidas pelas hipóteses legais previstas na cláusula anterior, dependerá da existência de base legal adequada, inclusive consentimento específico do titular, quando necessário, assegurados os direitos previstos na Lei nº 13.709/2018."}, {"id": "p098", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p099", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p100", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p101", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p102", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p103", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p104", "t": "[[ASSINATURAS]]"}]$inter$::jsonb, 'Rascunho só intermediação, revisão jurídica pendente');


CREATE TABLE public.locacao_intermediacoes (
  locacao_id uuid PRIMARY KEY REFERENCES public.locacoes(id) ON DELETE CASCADE,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  valor numeric(14,2) NOT NULL CHECK (valor > 0),
  vencimento date NOT NULL,
  status text NOT NULL DEFAULT 'aberta' CHECK (status IN ('aberta','recebida')),
  recebida_em date,
  recebido_por uuid,
  criado_em timestamptz NOT NULL DEFAULT now(),
  CHECK ((status = 'aberta' AND recebida_em IS NULL AND recebido_por IS NULL)
      OR (status = 'recebida' AND recebida_em IS NOT NULL AND recebido_por IS NOT NULL))
);
CREATE INDEX locacao_intermediacoes_org_vencimento ON public.locacao_intermediacoes(organization_id, vencimento);
ALTER TABLE public.locacao_intermediacoes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.locacao_intermediacoes FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.locacao_intermediacoes TO service_role;

-- Chamada pelo gatilho de entrega das chaves. A chave primária impede duplicação até entre duas chamadas simultâneas.
CREATE OR REPLACE FUNCTION public.locacao_fin_criar_contrato(_l public.locacoes) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _cfg public.locacao_fin_config := public.locacao_fin_cfg(_l.organization_id); _id uuid;
BEGIN
  IF _l.chave_em IS NULL OR _l.aluguel IS NULL THEN RETURN NULL; END IF;
  IF _l.sem_administracao THEN
    INSERT INTO public.locacao_intermediacoes (locacao_id, organization_id, valor, vencimento)
    VALUES (_l.id, _l.organization_id, _l.aluguel, _l.chave_em)
    ON CONFLICT (locacao_id) DO NOTHING;
    RETURN NULL;
  END IF;
  INSERT INTO public.locacao_contratos (organization_id, locacao_id, endereco, inquilino_nome, garantia, aluguel, taxa_adm,
    condominio, iptu, dia_vencimento, inicio, proximo_reajuste, indice)
  VALUES (_l.organization_id, _l.id, _l.endereco, nullif(btrim(coalesce(_l.candidato->>'nome', '')), ''), _l.garantia,
    _l.aluguel, _l.taxa_adm, _l.condominio, _l.iptu, least(28, extract(day FROM _l.chave_em)::integer), _l.chave_em,
    (_l.chave_em + interval '1 year')::date, _cfg.indice)
  ON CONFLICT (locacao_id) DO NOTHING RETURNING id INTO _id;
  IF _id IS NOT NULL THEN
    INSERT INTO public.locacao_fin_eventos (organization_id, contrato_id, acao, descricao, ator_id)
    VALUES (_l.organization_id, _id, 'contrato_criado', 'Contrato criado na entrega das chaves (' ||
      to_char(_l.chave_em, 'DD/MM/YYYY') || ') — aguardando o Financeiro completar e ativar', auth.uid());
  END IF;
  RETURN _id;
END $$;
REVOKE ALL ON FUNCTION public.locacao_fin_criar_contrato(public.locacoes) FROM PUBLIC, anon, authenticated;

-- O painel preserva a mesma fonte das cobranças mensais e traz intermediações em coleção separada.
CREATE OR REPLACE FUNCTION public.locacao_fin_painel(_competencia date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _org uuid := public.locacao_fin_ctx(); _comp date := date_trunc('month', coalesce(_competencia, public.locacao_fin_hoje()))::date;
BEGIN
  RETURN jsonb_build_object(
    'competencia', _comp, 'hoje', public.locacao_fin_hoje(),
    'config', to_jsonb(public.locacao_fin_cfg(_org)) - 'organization_id' - 'atualizado_por',
    'pode_regras', public.locacao_fin_pode_regras(auth.uid(), _org),
    'contratos', (SELECT coalesce(jsonb_agg(public.locacao_fin_ct_json(ct) ORDER BY ct.numero), '[]')
                    FROM public.locacao_contratos ct WHERE ct.organization_id = _org),
    'cobrancas', (SELECT coalesce(jsonb_agg(public.locacao_fin_cob_json(c) ORDER BY c.vencimento, c.id), '[]')
                    FROM public.locacao_cobrancas c WHERE c.organization_id = _org AND c.competencia = _comp),
    'atrasadas_antes', (SELECT coalesce(jsonb_agg(public.locacao_fin_cob_json(c) ORDER BY c.vencimento), '[]')
                    FROM public.locacao_cobrancas c WHERE c.organization_id = _org AND c.competencia < _comp
                     AND c.status = 'aberta' AND c.vencimento < public.locacao_fin_hoje()),
    'intermediacoes', (SELECT coalesce(jsonb_agg(jsonb_build_object(
                     'locacao_id', i.locacao_id, 'codigo', 'LOC-' || lpad(l.numero::text, 4, '0'),
                     'endereco', l.endereco, 'valor', i.valor, 'vencimento', i.vencimento,
                     'status', i.status, 'recebida_em', i.recebida_em)
                     ORDER BY i.vencimento DESC, i.locacao_id), '[]')
                     FROM public.locacao_intermediacoes i JOIN public.locacoes l ON l.id = i.locacao_id
                     WHERE i.organization_id = _org),
    'faltam_gerar', (SELECT count(*) FROM public.locacao_contratos ct WHERE ct.organization_id = _org AND ct.situacao = 'ativo'
                      AND date_trunc('month', ct.inicio) <= _comp
                      AND NOT EXISTS (SELECT 1 FROM public.locacao_cobrancas c WHERE c.contrato_id = ct.id AND c.competencia = _comp)));
END $$;
REVOKE ALL ON FUNCTION public.locacao_fin_painel(date) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.locacao_fin_painel(date) TO authenticated;

CREATE OR REPLACE FUNCTION public.locacao_fin_intermediacao_receber(_id uuid, _data date) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _org uuid := public.locacao_fin_ctx(); _x public.locacao_intermediacoes;
BEGIN
  IF _id IS NULL OR _data IS NULL OR _data > public.locacao_fin_hoje() THEN
    RAISE EXCEPTION 'Informe uma data de recebimento válida (não futura).' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO _x FROM public.locacao_intermediacoes WHERE locacao_id = _id AND organization_id = _org FOR UPDATE;
  IF _x.locacao_id IS NULL THEN RAISE EXCEPTION 'Intermediação não encontrada nesta imobiliária.' USING ERRCODE = '42501'; END IF;
  IF _x.status = 'recebida' THEN RAISE EXCEPTION 'Intermediação já recebida.' USING ERRCODE = '22023'; END IF;
  UPDATE public.locacao_intermediacoes SET status = 'recebida', recebida_em = _data, recebido_por = auth.uid()
   WHERE locacao_id = _id AND organization_id = _org;
  RETURN jsonb_build_object('ok', true);
END $$;
REVOKE ALL ON FUNCTION public.locacao_fin_intermediacao_receber(uuid, date) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.locacao_fin_intermediacao_receber(uuid, date) TO authenticated;

-- Seleção da variante pela modalidade, com conferência no servidor na hora de guardar o PDF.
CREATE OR REPLACE FUNCTION public.locacao_modelo_garantia_ok(_garantia text, _chave text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path TO '' AS $$
  SELECT coalesce(CASE _garantia
    WHEN 'fiador' THEN replace(_chave, '_intermediacao', '') = 'fiador'
    WHEN 'caucao' THEN replace(_chave, '_intermediacao', '') IN ('caucao_dinheiro', 'caucao_imovel')
    WHEN 'outras' THEN replace(_chave, '_intermediacao', '') = 'caucao_imovel'
    WHEN 'seguro_fianca' THEN replace(_chave, '_intermediacao', '') IN ('seguro_porto', 'seguro_pottencial', 'seguro_tokio', 'seguro_almada')
    WHEN 'loft' THEN replace(_chave, '_intermediacao', '') = 'loft'
    ELSE false END, false)
$$;

CREATE OR REPLACE FUNCTION public.locacao_modelos_listar() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _org uuid := public.locacao_modelo_exige();
BEGIN
  RETURN (SELECT coalesce(jsonb_agg(public.locacao_modelo_json(public.locacao_modelo_atual(_org, p.chave)) - 'paragrafos'
      || jsonb_build_object('versoes', (SELECT count(*) FROM public.locacao_modelos o WHERE o.organization_id = _org
                                          AND o.chave = p.chave))
      ORDER BY array_position(ARRAY['fiador', 'caucao_dinheiro', 'caucao_imovel', 'seguro_porto', 'seguro_pottencial',
        'seguro_tokio', 'seguro_almada', 'loft'], replace(p.chave, '_intermediacao', '')), p.chave), '[]'::jsonb)
    FROM (SELECT DISTINCT chave FROM public.locacao_modelos WHERE organization_id IS NULL) p);
END $$;

CREATE OR REPLACE FUNCTION public.locacao_montagem_ler(_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _l public.locacoes := public.locacao_montagem_pega(_id); _o public.organizations; _c jsonb;
BEGIN
  SELECT * INTO _o FROM public.organizations WHERE id = _l.organization_id;
  SELECT campos INTO _c FROM public.locacao_montagem WHERE locacao_id = _id AND organization_id = _l.organization_id;
  RETURN jsonb_build_object('campos', coalesce(_c, '{}'::jsonb),
    'contrato', public.locacao_contrato_valores(_l),
    'administradora', jsonb_build_object('nome', coalesce(_o.razao_social, _o.nome),
      'cnpj', _o.cnpj, 'creci', _o.creci, 'cidade', _o.cidade, 'uf', _o.uf),
    'modelos', (SELECT coalesce(jsonb_object_agg(k.chave, public.locacao_modelo_json(public.locacao_modelo_atual(_l.organization_id, k.chave))), '{}'::jsonb)
                  FROM unnest(ARRAY['fiador', 'caucao_dinheiro', 'caucao_imovel', 'seguro_porto', 'seguro_pottencial',
                    'seguro_tokio', 'seguro_almada', 'loft']) k0
                    CROSS JOIN LATERAL (SELECT k0 || CASE WHEN _l.sem_administracao THEN '_intermediacao' ELSE '' END AS chave) k
                    WHERE public.locacao_modelo_garantia_ok(_l.garantia, k.chave)),
    'apolice', (SELECT a.numero FROM public.locacao_anexos a WHERE a.locacao_id = _l.id AND a.tipo = 'apolice'
                 ORDER BY a.enviado_em DESC LIMIT 1));
END $$;

CREATE OR REPLACE FUNCTION public.locacao_minuta_registrar(_id uuid, _path text, _nome text, _origem text,
  _modelo_chave text DEFAULT NULL, _modelo_versao integer DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _l public.locacoes := public.locacao_pega(_id); _m jsonb; _v integer; _o text; _nm text; _novo uuid;
  _mod public.locacao_modelos;
BEGIN
  PERFORM public.locacao_exige(_l, ARRAY['minuta'], 'contratos');
  IF _origem IS NULL OR _origem NOT IN ('anexo', 'gerada') THEN
    RAISE EXCEPTION 'Origem inválida.' USING ERRCODE = '22023';
  END IF;
  IF _path IS NULL OR _path !~ ('^' || _l.organization_id::text || '/' || _l.id::text || '/minutas/[0-9a-f-]{36}[.](pdf|doc|docx)$')
     OR NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'locacao-documentos' AND o.name = _path) THEN
    RAISE EXCEPTION 'Arquivo da minuta não encontrado.' USING ERRCODE = '22023';
  END IF;
  IF _origem = 'gerada' THEN
    IF _path !~ '[.]pdf$' OR NOT public.locacao_modelo_garantia_ok(_l.garantia, _modelo_chave)
      OR _l.sem_administracao IS DISTINCT FROM (_modelo_chave LIKE '%_intermediacao') THEN
      RAISE EXCEPTION 'Esta garantia não tem modelo para gerar a minuta (PDF): anexe a minuta feita por fora.' USING ERRCODE = '22023';
    END IF;
    _mod := public.locacao_modelo_atual(_l.organization_id, _modelo_chave);
    IF _modelo_versao IS DISTINCT FROM (CASE WHEN _mod.organization_id IS NULL THEN 0 ELSE _mod.versao END) THEN
      RAISE EXCEPTION 'O modelo de contrato mudou enquanto você montava: recarregue e gere de novo.' USING ERRCODE = '22023';
    END IF;
  ELSIF _modelo_chave IS NOT NULL OR _modelo_versao IS NOT NULL THEN
    RAISE EXCEPTION 'Origem inválida.' USING ERRCODE = '22023';
  END IF;
  -- Tipo real gravado no storage tem de bater com a extensão (o navegador declara o tipo no upload).
  IF (SELECT o.metadata->>'mimetype' FROM storage.objects o WHERE o.bucket_id = 'locacao-documentos' AND o.name = _path)
     IS DISTINCT FROM (CASE WHEN _path LIKE '%.pdf' THEN 'application/pdf'
       WHEN _path LIKE '%.doc' THEN 'application/msword'
       ELSE 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' END) THEN
    RAISE EXCEPTION 'O tipo do arquivo não confere com a extensão (envie PDF ou Word).' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.locacao_minutas WHERE storage_path = _path) THEN
    RAISE EXCEPTION 'Arquivo já registrado.' USING ERRCODE = '22023';
  END IF;
  _m := _l.minuta;
  _o := CASE WHEN coalesce((_m->>'externa')::boolean, false) AND _origem = 'anexo' THEN 'externa' ELSE _origem END;
  _nm := left(coalesce(nullif(btrim(_nome), ''), 'minuta'), 200);
  -- A locação está travada (FOR UPDATE em locacao_pega): duas gravações seguidas não pegam o mesmo número.
  SELECT coalesce(max(versao), 0) + 1 INTO _v FROM public.locacao_minutas WHERE locacao_id = _l.id;
  INSERT INTO public.locacao_minutas (organization_id, locacao_id, versao, origem, storage_path, nome_arquivo, enviado_por,
    modelo_chave, modelo_versao)
  VALUES (_l.organization_id, _l.id, _v, _o, _path, _nm, auth.uid(), CASE WHEN _o = 'gerada' THEN _modelo_chave END,
    CASE WHEN _o = 'gerada' THEN _modelo_versao END) RETURNING id INTO _novo;
  PERFORM public.locacao_evento(_l, 'contratos', 'Minuta v' || _v || ' '
    || CASE _o WHEN 'gerada' THEN 'gerada pelo modelo "' || _mod.titulo || '" (texto '
         || CASE WHEN _modelo_versao = 0 THEN 'padrão' ELSE 'v' || _modelo_versao END || ') e guardada' WHEN 'externa' THEN 'de outra RE/MAX anexada'
       ELSE 'anexada' END || ' (' || _nm || ')');
  -- Versão nova depois do envio: volta a "elaborando" para o corretor conferir a versão nova.
  IF coalesce(_m->>'estado', '') IN ('', 'com_corretor', 'aprovada') THEN
    IF _m->>'estado' IN ('com_corretor', 'aprovada') THEN
      PERFORM public.locacao_evento(_l, 'contratos', 'Minuta volta a "elaborando": a versão v' || _v
        || ' ainda não foi enviada ao corretor');
    END IF;
    _m := _m || jsonb_build_object('estado', 'elaborando');
    UPDATE public.locacoes SET minuta = _m, atualizado_em = now() WHERE id = _l.id;
  ELSE
    UPDATE public.locacoes SET atualizado_em = now() WHERE id = _l.id;
  END IF;
  RETURN jsonb_build_object('id', _novo, 'versao', _v);
END $$;
-- A variante fiador também exige o bloco de assinatura do fiador.
CREATE OR REPLACE FUNCTION public.locacao_modelo_validar(_chave text, _p jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path TO '' AS $$
DECLARE _e jsonb; _t text; _out jsonb := '[]'::jsonb; _ids text[] := ARRAY[]::text[]; _x text; _bl text[] := ARRAY[]::text[];
BEGIN
  IF _p IS NULL OR jsonb_typeof(_p) <> 'array' OR jsonb_array_length(_p) < 5 OR jsonb_array_length(_p) > 400 THEN
    RAISE EXCEPTION 'Modelo inválido: lista de cláusulas vazia ou grande demais.' USING ERRCODE = '22023';
  END IF;
  FOR _e IN SELECT value FROM jsonb_array_elements(_p) LOOP
    IF jsonb_typeof(_e) <> 'object' OR jsonb_typeof(_e->'t') IS DISTINCT FROM 'string' OR jsonb_typeof(_e->'id') IS DISTINCT FROM 'string'
       OR (_e ? 'trava' AND jsonb_typeof(_e->'trava') <> 'boolean')
       OR (_e ? 'dest' AND (_e->>'dest') NOT IN ('residencial', 'comercial'))
       OR (_e ? 'cond' AND (_e->>'cond') NOT IN ('isencao_multa'))
       OR (_e ? 'adaptado' AND jsonb_typeof(_e->'adaptado') <> 'boolean')
       OR (_e->>'id') !~ '^[a-z0-9_-]{1,24}$' THEN
      RAISE EXCEPTION 'Modelo inválido: cláusula mal formada.' USING ERRCODE = '22023';
    END IF;
    _t := btrim(_e->>'t');
    IF length(_t) < 1 OR length(_t) > 8000 THEN
      RAISE EXCEPTION 'Cláusula vazia ou longa demais (máx. 8.000 caracteres).' USING ERRCODE = '22023';
    END IF;
    IF (_e->>'id') = ANY (_ids) THEN RAISE EXCEPTION 'Modelo inválido: cláusula repetida.' USING ERRCODE = '22023'; END IF;
    _ids := _ids || (_e->>'id');
    -- Bloco automático: parágrafo que é só [[NOME]].
    IF _t ~ '^\[\[[A-Z_]+\]\]$' THEN
      _x := substring(_t FROM 3 FOR length(_t) - 4);
      IF NOT (_x = ANY (public.locacao_modelo_blocos())) THEN
        RAISE EXCEPTION 'Bloco automático desconhecido: [[%]]', _x USING ERRCODE = '22023';
      END IF;
      IF _x = ANY (_bl) THEN RAISE EXCEPTION 'Bloco automático repetido: [[%]]', _x USING ERRCODE = '22023'; END IF;
      _bl := _bl || _x;
    ELSIF _t ~ '\[\[' THEN
      RAISE EXCEPTION 'Bloco automático [[...]] tem de ficar sozinho no parágrafo.' USING ERRCODE = '22023';
    ELSE
      FOR _x IN SELECT (regexp_matches(_t, '\[([A-Z_]+)\]', 'g'))[1] LOOP
        IF NOT (_x = ANY (public.locacao_modelo_campos())) THEN
          RAISE EXCEPTION 'Campo que não existe: [%]. Use um dos campos da lista.', _x USING ERRCODE = '22023';
        END IF;
      END LOOP;
    END IF;
    _out := _out || jsonb_strip_nulls(jsonb_build_object('id', _e->>'id', 't', _t,
      'trava', CASE WHEN coalesce((_e->>'trava')::boolean, false) THEN true END, 'dest', _e->>'dest', 'cond', _e->>'cond',
      'adaptado', CASE WHEN coalesce((_e->>'adaptado')::boolean, false) THEN true END));
  END LOOP;
  FOREACH _x IN ARRAY ARRAY['LOCADOR', 'LOCATARIO', 'OBJETO', 'PRAZO', 'ASSINATURAS']
                 || CASE WHEN _chave IN ('fiador', 'fiador_intermediacao') THEN ARRAY['FIADOR'] ELSE ARRAY[]::text[] END LOOP
    IF NOT (_x = ANY (_bl)) THEN
      RAISE EXCEPTION 'Falta o bloco automático [[%]] (dados que o sistema preenche).', _x USING ERRCODE = '22023';
    END IF;
  END LOOP;
  RETURN _out;
END $$;
COMMIT;
